using System.Globalization;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>
/// A single rename operation, stored as a loose property bag.
/// <para>
/// The rules.json contract reuses the same key name with different JSON types across
/// operations (for example <c>from</c> is an integer for <c>remove</c> but a string for
/// <c>translate</c>), so a strongly typed DTO per key is not possible. Every operation
/// therefore reads the keys it cares about through the tolerant accessors below.
/// </para>
/// </summary>
public sealed class RuleStep
{
    /// <summary>Operation id, e.g. <c>replace</c>. Never null.</summary>
    public string Op { get; set; } = string.Empty;

    /// <summary>Raw values keyed by JSON property name. Values are string, long, double or bool.</summary>
    public Dictionary<string, object?> Values { get; } = new(StringComparer.Ordinal);

    public RuleStep() { }

    public RuleStep(string op) => Op = op;

    public object? this[string key]
    {
        get => Values.TryGetValue(key, out var v) ? v : null;
        set => Values[key] = value;
    }

    public bool Has(string key) => Values.ContainsKey(key);

    public string GetString(string key, string fallback)
    {
        if (!Values.TryGetValue(key, out var v) || v is null) return fallback;
        return v switch
        {
            string s => s,
            bool b => b ? "true" : "false",
            long l => l.ToString(CultureInfo.InvariantCulture),
            double d => d.ToString(CultureInfo.InvariantCulture),
            _ => fallback,
        };
    }

    public int GetInt(string key, int fallback)
    {
        if (!Values.TryGetValue(key, out var v) || v is null) return fallback;
        switch (v)
        {
            case long l:
                if (l > int.MaxValue) return int.MaxValue;
                if (l < int.MinValue) return int.MinValue;
                return (int)l;
            case double d:
                if (double.IsNaN(d)) return fallback;
                if (d > int.MaxValue) return int.MaxValue;
                if (d < int.MinValue) return int.MinValue;
                return (int)Math.Truncate(d);
            case bool b:
                return b ? 1 : 0;
            case string s:
                return int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed)
                    ? parsed
                    : fallback;
            default:
                return fallback;
        }
    }

    public bool GetBool(string key, bool fallback)
    {
        if (!Values.TryGetValue(key, out var v) || v is null) return fallback;
        return v switch
        {
            bool b => b,
            long l => l != 0,
            double d => d != 0,
            string s => bool.TryParse(s, out var parsed) ? parsed : fallback,
            _ => fallback,
        };
    }

    public RuleStep Clone()
    {
        var copy = new RuleStep(Op);
        foreach (var kv in Values) copy.Values[kv.Key] = kv.Value;
        return copy;
    }

    internal static RuleStep FromJson(JsonElement element)
    {
        var step = new RuleStep();
        if (element.ValueKind != JsonValueKind.Object) return step;

        foreach (var property in element.EnumerateObject())
        {
            if (string.Equals(property.Name, "op", StringComparison.Ordinal))
            {
                step.Op = property.Value.ValueKind == JsonValueKind.String
                    ? property.Value.GetString() ?? string.Empty
                    : string.Empty;
                continue;
            }

            step.Values[property.Name] = ToClrValue(property.Value);
        }

        return step;
    }

    private static object? ToClrValue(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.String => value.GetString(),
        JsonValueKind.True => true,
        JsonValueKind.False => false,
        JsonValueKind.Number => value.TryGetInt64(out var l) ? l : value.GetDouble(),
        _ => null,
    };
}

