using System.Globalization;
using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

public enum ApplyTo
{
    /// <summary>Steps operate on the base name only (rule 3).</summary>
    Name,

    /// <summary>Steps operate on the whole file name including the extension (rule 3).</summary>
    NameAndExtension,
}

public enum SortMode
{
    Name,
    Created,
    Modified,
}

/// <summary>The parsed content of a rules.json document.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public static string ApplyToToJson(ApplyTo value) =>
        value == ApplyTo.NameAndExtension ? "nameAndExtension" : "name";

    public static string SortToJson(SortMode value) => value switch
    {
        SortMode.Created => "created",
        SortMode.Modified => "modified",
        _ => "name",
    };

    /// <summary>
    /// Parses rules.json. Unknown enum spellings fall back to the first listed option
    /// (see docs/DECISIONS.md, D-04) rather than throwing.
    /// </summary>
    public static RuleSet Parse(string json)
    {
        var options = new JsonDocumentOptions
        {
            AllowTrailingCommas = true,
            CommentHandling = JsonCommentHandling.Skip,
        };

        using var document = JsonDocument.Parse(json, options);
        var root = document.RootElement;
        if (root.ValueKind != JsonValueKind.Object)
            throw new FormatException("rules.json root must be a JSON object.");

        var ruleSet = new RuleSet();

        if (root.TryGetProperty("applyTo", out var applyTo) && applyTo.ValueKind == JsonValueKind.String)
        {
            ruleSet.ApplyTo = string.Equals(applyTo.GetString(), "nameAndExtension", StringComparison.OrdinalIgnoreCase)
                ? ApplyTo.NameAndExtension
                : ApplyTo.Name;
        }

        if (root.TryGetProperty("sort", out var sort) && sort.ValueKind == JsonValueKind.String)
        {
            ruleSet.Sort = (sort.GetString() ?? string.Empty).ToLowerInvariant() switch
            {
                "created" => SortMode.Created,
                "modified" => SortMode.Modified,
                _ => SortMode.Name,
            };
        }

        if (root.TryGetProperty("steps", out var steps) && steps.ValueKind == JsonValueKind.Array)
        {
            foreach (var element in steps.EnumerateArray())
                ruleSet.Steps.Add(RuleStep.FromJson(element));
        }

        return ruleSet;
    }

    public static RuleSet Load(string path) => Parse(File.ReadAllText(path, Encoding.UTF8));

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps) copy.Steps.Add(step.Clone());
        return copy;
    }

    /// <summary>Serializes back to the rules.json contract shape (UTF-8 without BOM when saved).</summary>
    public string ToJson()
    {
        var builder = new StringBuilder();
        builder.Append("{\n");
        builder.Append("  \"applyTo\": ").Append(JsonText.Quote(ApplyToToJson(ApplyTo))).Append(",\n");
        builder.Append("  \"sort\": ").Append(JsonText.Quote(SortToJson(Sort))).Append(",\n");
        builder.Append("  \"steps\": [");

        if (Steps.Count == 0)
        {
            builder.Append("]\n}\n");
            return builder.ToString();
        }

        builder.Append('\n');
        for (var i = 0; i < Steps.Count; i++)
        {
            builder.Append("    ").Append(StepToJson(Steps[i]));
            builder.Append(i == Steps.Count - 1 ? "\n" : ",\n");
        }

        builder.Append("  ]\n}\n");
        return builder.ToString();
    }

    private static string StepToJson(RuleStep step)
    {
        var builder = new StringBuilder();
        builder.Append("{\"op\": ").Append(JsonText.Quote(step.Op));

        // Emit the catalog fields in declaration order so saved files stay stable and readable,
        // then any extra keys the user hand-authored, so nothing is silently dropped.
        var written = new HashSet<string>(StringComparer.Ordinal);
        foreach (var field in OpCatalog.FieldsFor(step.Op))
        {
            written.Add(field.Key);
            builder.Append(", ").Append(JsonText.Quote(field.Key)).Append(": ");
            builder.Append(ValueToJson(step.Has(field.Key) ? step[field.Key] : field.Default, field));
        }

        foreach (var kv in step.Values)
        {
            if (written.Contains(kv.Key)) continue;
            builder.Append(", ").Append(JsonText.Quote(kv.Key)).Append(": ").Append(ValueToJson(kv.Value, null));
        }

        builder.Append('}');
        return builder.ToString();
    }

    private static string ValueToJson(object? value, OpField? field)
    {
        if (value is null && field is not null) value = field.Default;

        return value switch
        {
            null => "null",
            bool b => b ? "true" : "false",
            long l => l.ToString(CultureInfo.InvariantCulture),
            int i => i.ToString(CultureInfo.InvariantCulture),
            double d => d.ToString("R", CultureInfo.InvariantCulture),
            string s => JsonText.Quote(s),
            _ => JsonText.Quote(Convert.ToString(value, CultureInfo.InvariantCulture) ?? string.Empty),
        };
    }
}

