using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// Minimal deterministic JSON text helpers.
/// <para>
/// The output contracts require byte-identical files for identical inputs, so the writers here
/// are hand-rolled: they always emit LF line endings (System.Text.Json's indented writer uses
/// <see cref="Environment.NewLine"/> on .NET 8) and they escape lone surrogates that Windows
/// file names can technically contain but UTF-8 encoding cannot represent.
/// </para>
/// </summary>
public static class JsonText
{
    /// <summary>UTF-8 without a byte order mark, as both output contracts require.</summary>
    public static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    public static string Quote(string? value)
    {
        var builder = new StringBuilder((value?.Length ?? 0) + 2);
        builder.Append('"');
        Escape(builder, value);
        builder.Append('"');
        return builder.ToString();
    }

    public static void Escape(StringBuilder builder, string? value)
    {
        if (string.IsNullOrEmpty(value)) return;

        for (var i = 0; i < value.Length; i++)
        {
            var c = value[i];
            switch (c)
            {
                case '"': builder.Append("\\\""); break;
                case '\\': builder.Append("\\\\"); break;
                case '\b': builder.Append("\\b"); break;
                case '\f': builder.Append("\\f"); break;
                case '\n': builder.Append("\\n"); break;
                case '\r': builder.Append("\\r"); break;
                case '\t': builder.Append("\\t"); break;
                default:
                    if (c < 0x20 || c == 0x7F)
                    {
                        AppendUnicodeEscape(builder, c);
                    }
                    else if (char.IsSurrogate(c))
                    {
                        // Only a well-formed pair may be written raw; anything else is escaped so
                        // the file stays valid UTF-8 instead of being mangled into U+FFFD.
                        if (char.IsHighSurrogate(c) && i + 1 < value.Length && char.IsLowSurrogate(value[i + 1]))
                        {
                            builder.Append(c).Append(value[i + 1]);
                            i++;
                        }
                        else
                        {
                            AppendUnicodeEscape(builder, c);
                        }
                    }
                    else
                    {
                        builder.Append(c);
                    }

                    break;
            }
        }
    }

    private static void AppendUnicodeEscape(StringBuilder builder, char c) =>
        builder.Append("\\u").Append(((int)c).ToString("x4"));

    /// <summary>Writes text as UTF-8 without a BOM, normalising CRLF to LF first.</summary>
    public static void WriteFile(string path, string content)
    {
        var normalised = content.Replace("\r\n", "\n").Replace('\r', '\n');
        var directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory)) Directory.CreateDirectory(directory);
        File.WriteAllText(path, normalised, Utf8NoBom);
    }
}

