using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

public enum OpFieldKind
{
    Text,
    Int,
    Bool,
    Choice,
}

/// <summary>One editable JSON key of an operation.</summary>
public sealed class OpField
{
    public OpField(string key, string label, OpFieldKind kind, object? defaultValue, string[]? choices = null, string hint = "")
    {
        Key = key;
        Label = label;
        Kind = kind;
        Default = defaultValue;
        Choices = choices ?? Array.Empty<string>();
        Hint = hint;
    }

    public string Key { get; }

    public string Label { get; }

    public OpFieldKind Kind { get; }

    public object? Default { get; }

    public string[] Choices { get; }

    public string Hint { get; }
}

/// <summary>Static description of one operation: used by the rule editor, the serializer and the help text.</summary>
public sealed class OpInfo
{
    public OpInfo(string op, string title, string summary, params OpField[] fields)
    {
        Op = op;
        Title = title;
        Summary = summary;
        Fields = fields;
    }

    public string Op { get; }

    /// <summary>Display title (Traditional Chinese) shown in the rule editor.</summary>
    public string Title { get; }

    /// <summary>One-line explanation of the semantics shown under the title.</summary>
    public string Summary { get; }

    public OpField[] Fields { get; }
}

/// <summary>
/// The single source of truth for the 14 operations: their keys, defaults and display metadata.
/// Engine defaults are read from here so the GUI preview and the headless run can never diverge.
/// </summary>
public static class OpCatalog
{
    public const string Replace = "replace";
    public const string Insert = "insert";
    public const string Remove = "remove";
    public const string Sequence = "sequence";
    public const string Case = "case";
    public const string Extension = "extension";
    public const string Pad = "pad";
    public const string Trim = "trim";
    public const string Slug = "slug";
    public const string Translate = "translate";
    public const string NumberFormat = "numberFormat";
    public const string Extract = "extract";
    public const string Template = "template";
    public const string DedupeChars = "dedupeChars";

