namespace BatchRenameStudio.Core;

/// <summary>File-name splitting, reassembly and validity rules (spec rules 2, 6 and 7).</summary>
public static class NameRules
{
    public const int MaxNameLength = 255;

    /// <summary>Characters that make a proposed name invalid, per rule 7.</summary>
    public static readonly char[] IllegalCharacters = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedBaseNames = BuildReservedNames();

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (var i = 1; i <= 9; i++)
        {
            set.Add("COM" + i);
            set.Add("LPT" + i);
        }

        return set;
    }

    /// <summary>
    /// Rule 2: split at the LAST dot. When that dot is at index 0 (or absent) the whole name is
    /// the base and the extension is empty, so ".gitignore" keeps its leading dot in the base.
    /// </summary>
    public static (string Base, string Ext) Split(string name)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0) return (name[..dot], name[(dot + 1)..]);
        return (name, string.Empty);
    }

    /// <summary>Rule 6: base + "." + ext when ext is non-empty, otherwise base alone.</summary>
    public static string Join(string baseName, string ext) =>
        ext.Length == 0 ? baseName : baseName + "." + ext;

    public static bool IsReservedBaseName(string baseName) => ReservedBaseNames.Contains(baseName);

    /// <summary>
    /// Rule 7 "invalid" test. <paramref name="reason"/> receives a short human-readable cause.
    /// </summary>
    public static bool IsInvalidName(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "proposed name is empty";
            return true;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"proposed name is {proposed.Length} characters (limit {MaxNameLength})";
            return true;
        }

        foreach (var c in proposed)
        {
            if (c < ' ')
            {
                reason = $"contains control character U+{(int)c:X4}";
                return true;
            }

            if (Array.IndexOf(IllegalCharacters, c) >= 0)
            {
                reason = $"contains illegal character '{c}'";
                return true;
            }
        }

        var (baseName, _) = Split(proposed);
        if (IsReservedBaseName(baseName))
        {
            reason = $"'{baseName}' is a reserved device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }
}

