/// <summary>Per-file state threaded through the step chain.</summary>
public sealed class StepContext
{
    public StepContext(string originalName, ApplyTo applyTo, int index)
    {
        OriginalName = originalName;
        var (baseName, ext) = NameRules.Split(originalName);
        OriginalBase = baseName;
        OriginalExt = ext;
        CurrentExt = ext;
        ApplyTo = applyTo;
        Index = index;
    }

    public string OriginalName { get; }

    public string OriginalBase { get; }

    /// <summary>The extension of the ORIGINAL file per rule 2 — what <c>{ext}</c> always resolves to.</summary>
    public string OriginalExt { get; }

    /// <summary>
    /// The extension carried alongside the target string under <see cref="Core.ApplyTo.Name"/>.
    /// Only the <c>extension</c> operation mutates it. Unused under nameAndExtension, where the
    /// extension lives inside the target string itself.
    /// </summary>
    public string CurrentExt { get; set; }

    public ApplyTo ApplyTo { get; }

    /// <summary>0-based position in processing order (spec rule 5).</summary>
    public int Index { get; }
}

