/// <summary>
/// The 14 operations. Every method takes the current target string and returns the next one;
/// only <c>extension</c> under applyTo="name" writes through to <see cref="StepContext.CurrentExt"/>
/// instead, which is why its trace entry always shows before == after.
/// </summary>
public static class StepOps
{
    /// <summary>Guards against catastrophic backtracking in user-supplied patterns.</summary>
    public static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    private static readonly Regex SequenceToken =
