        while (collapsed.StartsWith(separator, StringComparison.Ordinal))
            collapsed = collapsed[separator.Length..];
        while (collapsed.EndsWith(separator, StringComparison.Ordinal))
            collapsed = collapsed[..^separator.Length];

        return collapsed;
    }

    private static string Translate(RuleStep step, string target)
    {
        var from = step.GetString("from", string.Empty);
        if (from.Length == 0) return target;
        var to = step.GetString("to", string.Empty);

        var map = new Dictionary<char, char?>();
        for (var k = 0; k < from.Length; k++)
        {
            if (map.ContainsKey(from[k])) continue; // first mapping wins
            map[from[k]] = k < to.Length ? to[k] : null; // beyond 'to' -> delete
        }

        var builder = new StringBuilder(target.Length);
        foreach (var c in target)
        {
            if (!map.TryGetValue(c, out var mapped))
            {
                builder.Append(c);
                continue;
            }

            if (mapped.HasValue) builder.Append(mapped.Value);
        }

        return builder.ToString();
    }

    private static string NumberFormat(RuleStep step, string target)
    {
        var width = step.GetInt("width", 0);

        var start = -1;
        for (var i = 0; i < target.Length; i++)
        {
            if (target[i] >= '0' && target[i] <= '9')
            {
                start = i;
                break;
            }
        }

        if (start < 0) return target;

        var end = start;
        while (end < target.Length && target[end] >= '0' && target[end] <= '9') end++;

        var runLength = end - start;
        if (runLength >= width) return target;

        return string.Concat(
            target.AsSpan(0, start),
            new string('0', width - runLength),
            target.AsSpan(start, runLength),
            target.AsSpan(end));
    }

    private static string Extract(RuleStep step, string target)
    {
        var pattern = step.GetString("pattern", string.Empty);
        var group = step.GetInt("group", 0);

        var options = RegexOptions.CultureInvariant;
        if (step.GetBool("ignoreCase", false)) options |= RegexOptions.IgnoreCase;

        Match match;
        try
        {
            match = new Regex(pattern, options, RegexTimeout).Match(target);
        }
        catch (ArgumentException)
        {
            return target; // invalid pattern -> inert step
        }
        catch (RegexMatchTimeoutException)
        {
            return target;
        }

        if (!match.Success) return string.Empty;
        if (group < 0 || group >= match.Groups.Count) return string.Empty;
        return match.Groups[group].Value;
    }

    private static string Template(RuleStep step, string target, StepContext context)
    {
        var format = step.GetString("format", "{name}");

        // One single pass so that substituted text is never re-scanned for tokens.
        return TemplateToken.Replace(format, match =>
        {
            var token = match.Value;
            switch (token)
            {
                case "{name}": return target;
                case "{ext}": return context.OriginalExt;
                case "{len}": return target.Length.ToString(CultureInfo.InvariantCulture);
            }

            var sequence = SequenceToken.Match(token);
            if (sequence.Success && sequence.Length == token.Length)
            {
                var width = sequence.Groups[1].Value.Length;
                return (context.Index + 1).ToString(CultureInfo.InvariantCulture).PadLeft(width, '0');
            }

            return token; // any other {...} stays literal
        });
    }

    private static string DedupeChars(string target)
    {
        if (target.Length == 0) return target;

        var builder = new StringBuilder(target.Length);
        var previous = '\0';
        var first = true;

        foreach (var c in target)
        {
            if (first || c != previous) builder.Append(c);
            previous = c;
            first = false;
        }

        return builder.ToString();
    }
}

