namespace BatchRenameStudio.Core;

public static class RenameStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

/// <summary>One entry of the <c>steps</c> array in a trace file.</summary>
public sealed class StepTrace
{
    public StepTrace(int index, string op, string before, string after)
    {
        Index = index;
        Op = op;
        Before = before;
        After = after;
    }

    public int Index { get; }

    public string Op { get; }

    public string Before { get; }

    public string After { get; }
}

/// <summary>Everything both output contracts need for one file.</summary>
public sealed class FileResult
{
    public FileResult(string original)
    {
        Original = original;
        Proposed = original;
    }

    public string Original { get; }

    public string Proposed { get; set; }

    public string Status { get; set; } = RenameStatus.Ok;

    public string Reason { get; set; } = string.Empty;

    public List<StepTrace> Steps { get; } = new();
}

public sealed class PlanSummary
{
    public int Total { get; set; }

    public int Ok { get; set; }

    public int Collision { get; set; }

    public int Unchanged { get; set; }

    public int Invalid { get; set; }
}

public sealed class PlanResult
{
    public PlanResult(string directory, RuleSet rules, List<FileResult> items)
    {
        Directory = directory;
        Rules = rules;
        Items = items;
        Summary = BuildSummary(items);
    }

    public string Directory { get; }

    public RuleSet Rules { get; }

    /// <summary>Items in processing order (spec rules 5 and 8).</summary>
    public List<FileResult> Items { get; }

    public PlanSummary Summary { get; }

    private static PlanSummary BuildSummary(List<FileResult> items)
    {
        var summary = new PlanSummary { Total = items.Count };
        foreach (var item in items)
        {
            switch (item.Status)
            {
                case RenameStatus.Ok: summary.Ok++; break;
                case RenameStatus.Collision: summary.Collision++; break;
                case RenameStatus.Unchanged: summary.Unchanged++; break;
                case RenameStatus.Invalid: summary.Invalid++; break;
            }
        }

        return summary;
    }
}

/// <summary>
/// The rename planner. Pure with respect to the file system: it reads names and timestamps and
/// never writes. The GUI preview, <c>--plan</c> and <c>--explain</c> all go through this one path,
/// so a preview can never disagree with a headless plan.
/// </summary>
public static class RenameEngine
{
    /// <summary>Enumerates regular files directly inside the folder, in processing order (rule 1 + rule 5).</summary>
    public static List<string> EnumerateFiles(string directory, SortMode sort)
    {
        var info = new DirectoryInfo(directory);
        if (!info.Exists) throw new DirectoryNotFoundException($"Directory not found: {directory}");

        var files = new List<FileInfo>(info.GetFiles());

        Comparison<FileInfo> comparison = sort switch
        {
            SortMode.Created => (a, b) =>
            {
                var c = a.CreationTimeUtc.CompareTo(b.CreationTimeUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            SortMode.Modified => (a, b) =>
            {
                var c = a.LastWriteTimeUtc.CompareTo(b.LastWriteTimeUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            // "name" is ordinal (codepoint) ascending and case-sensitive.
            _ => (a, b) => string.CompareOrdinal(a.Name, b.Name),
        };

        files.Sort(comparison);
        return files.ConvertAll(f => f.Name);
    }

    public static PlanResult Run(string directory, RuleSet rules)
    {
        var names = EnumerateFiles(directory, rules.Sort);
        return Run(directory, rules, names);
    }

    /// <summary>Overload used by the GUI, which already holds the enumerated names.</summary>
    public static PlanResult Run(string directory, RuleSet rules, List<string> orderedNames)
    {
        var items = new List<FileResult>(orderedNames.Count);

        for (var i = 0; i < orderedNames.Count; i++)
            items.Add(Project(orderedNames[i], rules, i));

        AssignStatuses(items, orderedNames);
        return new PlanResult(directory, rules, items);
    }

    /// <summary>Runs the step chain for one file and records its trace.</summary>
    public static FileResult Project(string name, RuleSet rules, int index)
    {
        var result = new FileResult(name);
        var context = new StepContext(name, rules.ApplyTo, index);
        var target = rules.ApplyTo == ApplyTo.NameAndExtension ? name : context.OriginalBase;

        for (var s = 0; s < rules.Steps.Count; s++)
        {
            var step = rules.Steps[s];
            var before = target;
            target = StepOps.Apply(step, target, context);
            result.Steps.Add(new StepTrace(s, step.Op, before, target));
        }

        result.Proposed = rules.ApplyTo == ApplyTo.NameAndExtension
            ? target
            : NameRules.Join(target, context.CurrentExt);

        return result;
    }

    /// <summary>Rule 7 status assignment; first match wins.</summary>
    private static void AssignStatuses(List<FileResult> items, List<string> existingNames)
    {
        var existing = new HashSet<string>(existingNames, StringComparer.OrdinalIgnoreCase);

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in items)
        {
            proposedCounts.TryGetValue(item.Proposed, out var count);
            proposedCounts[item.Proposed] = count + 1;
        }

        foreach (var item in items)
        {
            if (NameRules.IsInvalidName(item.Proposed, out var reason))
            {
                item.Status = RenameStatus.Invalid;
                item.Reason = reason;
                continue;
            }

            var hitsOtherExistingFile = existing.Contains(item.Proposed)
                && !string.Equals(item.Proposed, item.Original, StringComparison.OrdinalIgnoreCase);

            if (hitsOtherExistingFile)
            {
                item.Status = RenameStatus.Collision;
                item.Reason = "target name already exists in the folder";
                continue;
            }

            if (proposedCounts.TryGetValue(item.Proposed, out var count) && count > 1)
            {
                item.Status = RenameStatus.Collision;
                item.Reason = "several files map to the same target name";
                continue;
            }

            if (string.Equals(item.Proposed, item.Original, StringComparison.Ordinal))
            {
                item.Status = RenameStatus.Unchanged;
                item.Reason = string.Empty;
                continue;
            }

            item.Status = RenameStatus.Ok;
            item.Reason = string.Empty;
        }
    }
}

