using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>Writers for the two fixed output contracts. LF line endings, UTF-8 without BOM.</summary>
public static class PlanJson
{
    public const int SchemaVersion = 1;

    public static string BuildPlan(PlanResult result)
    {
        var builder = new StringBuilder();
        builder.Append("{\n");
        builder.Append("  \"schemaVersion\": ").Append(SchemaVersion).Append(",\n");
        builder.Append("  \"items\": [");

        if (result.Items.Count == 0)
        {
            builder.Append("],\n");
        }
        else
        {
            builder.Append('\n');
            for (var i = 0; i < result.Items.Count; i++)
            {
                var item = result.Items[i];
                builder.Append("    {\"original\": ").Append(JsonText.Quote(item.Original));
                builder.Append(", \"proposed\": ").Append(JsonText.Quote(item.Proposed));
                builder.Append(", \"status\": ").Append(JsonText.Quote(item.Status));
                builder.Append(", \"reason\": ").Append(JsonText.Quote(item.Reason));
                builder.Append('}');
                builder.Append(i == result.Items.Count - 1 ? "\n" : ",\n");
            }

            builder.Append("  ],\n");
        }

        var summary = result.Summary;
        builder.Append("  \"summary\": {\"total\": ").Append(Number(summary.Total));
        builder.Append(", \"ok\": ").Append(Number(summary.Ok));
        builder.Append(", \"collision\": ").Append(Number(summary.Collision));
        builder.Append(", \"unchanged\": ").Append(Number(summary.Unchanged));
        builder.Append(", \"invalid\": ").Append(Number(summary.Invalid));
        builder.Append("}\n}\n");

        return builder.ToString();
    }

    public static string BuildTrace(PlanResult result)
    {
        var builder = new StringBuilder();
        builder.Append("{\n");
        builder.Append("  \"schemaVersion\": ").Append(SchemaVersion).Append(",\n");
        builder.Append("  \"files\": [");

        if (result.Items.Count == 0)
        {
            builder.Append("]\n}\n");
            return builder.ToString();
        }

        builder.Append('\n');
        for (var i = 0; i < result.Items.Count; i++)
        {
            var item = result.Items[i];
            builder.Append("    {\n");
            builder.Append("      \"original\": ").Append(JsonText.Quote(item.Original)).Append(",\n");
            builder.Append("      \"steps\": [");

            if (item.Steps.Count == 0)
            {
                builder.Append("],\n");
            }
            else
            {
                builder.Append('\n');
                for (var s = 0; s < item.Steps.Count; s++)
                {
                    var step = item.Steps[s];
                    builder.Append("        {\"index\": ").Append(Number(step.Index));
                    builder.Append(", \"op\": ").Append(JsonText.Quote(step.Op));
                    builder.Append(", \"before\": ").Append(JsonText.Quote(step.Before));
                    builder.Append(", \"after\": ").Append(JsonText.Quote(step.After));
                    builder.Append('}');
                    builder.Append(s == item.Steps.Count - 1 ? "\n" : ",\n");
                }

                builder.Append("      ],\n");
            }

            builder.Append("      \"proposed\": ").Append(JsonText.Quote(item.Proposed)).Append(",\n");
            builder.Append("      \"status\": ").Append(JsonText.Quote(item.Status)).Append('\n');
            builder.Append("    }");
            builder.Append(i == result.Items.Count - 1 ? "\n" : ",\n");
        }

        builder.Append("  ]\n}\n");
        return builder.ToString();
    }

    private static string Number(int value) => value.ToString(CultureInfo.InvariantCulture);
}

