using System.Text;

namespace BatchRenameStudio.Core;

public sealed class RenamePair
{
    public RenamePair(string from, string to)
    {
        From = from;
        To = to;
    }

    public string From { get; }

    public string To { get; }
}

/// <summary>One executed rename batch, kept so it can be undone.</summary>
public sealed class RenameBatch
{
    public RenameBatch(string directory, List<RenamePair> pairs, DateTime timestampUtc)
    {
        Directory = directory;
        Pairs = pairs;
        TimestampUtc = timestampUtc;
    }

    public string Directory { get; }

    public List<RenamePair> Pairs { get; }

    public DateTime TimestampUtc { get; }
}

public sealed class RenameOutcome
{
    public int Renamed { get; set; }

    public List<string> Errors { get; } = new();

    public bool RolledBack { get; set; }

    public RenameBatch? Batch { get; set; }

    public bool Succeeded => Errors.Count == 0;
}

/// <summary>
/// Performs the actual renames.
/// <para>
/// Everything runs in two phases — every source first moves to a unique temporary name, then each
/// temporary moves to its final name. That makes swaps (a→b, b→a) and rotations work, and it means
/// a failure halfway through can always be rolled back because every original name is still free.
/// </para>
/// </summary>
public static class RenameExecutor
{
    public static RenameOutcome Execute(string directory, IReadOnlyList<RenamePair> pairs)
    {
        var outcome = new RenameOutcome();
        if (pairs.Count == 0) return outcome;

        var staged = new List<(string Temp, RenamePair Pair)>(pairs.Count);
        var finished = new List<RenamePair>(pairs.Count);

        try
        {
            foreach (var pair in pairs)
            {
                var source = Path.Combine(directory, pair.From);
                if (!File.Exists(source))
                    throw new FileNotFoundException($"'{pair.From}' no longer exists.", source);

                var temp = ReserveTempName(directory);
                File.Move(source, Path.Combine(directory, temp));
                staged.Add((temp, pair));
            }

            foreach (var (temp, pair) in staged)
            {
                File.Move(Path.Combine(directory, temp), Path.Combine(directory, pair.To));
                finished.Add(pair);
            }

            outcome.Renamed = finished.Count;
            outcome.Batch = new RenameBatch(directory, new List<RenamePair>(finished), DateTime.UtcNow);
            return outcome;
        }
        catch (Exception ex)
        {
            outcome.Errors.Add(ex.Message);
            outcome.RolledBack = TryRollback(directory, staged, finished, outcome);
            outcome.Renamed = 0;
            return outcome;
        }
    }

    /// <summary>Reverses a batch by running it backwards through the same two-phase move.</summary>
    public static RenameOutcome Undo(RenameBatch batch)
    {
        var reversed = new List<RenamePair>(batch.Pairs.Count);
        for (var i = batch.Pairs.Count - 1; i >= 0; i--)
            reversed.Add(new RenamePair(batch.Pairs[i].To, batch.Pairs[i].From));

        return Execute(batch.Directory, reversed);
    }

    private static bool TryRollback(
        string directory,
        List<(string Temp, RenamePair Pair)> staged,
        List<RenamePair> finished,
        RenameOutcome outcome)
    {
        var clean = true;

        // Undo the finalised moves first: their original names are still unoccupied.
        for (var i = finished.Count - 1; i >= 0; i--)
        {
            try
            {
                File.Move(Path.Combine(directory, finished[i].To), Path.Combine(directory, finished[i].From));
            }
            catch (Exception ex)
            {
                clean = false;
                outcome.Errors.Add($"rollback failed for '{finished[i].To}': {ex.Message}");
            }
        }

        var finalised = new HashSet<string>(finished.ConvertAll(p => p.From), StringComparer.OrdinalIgnoreCase);
        for (var i = staged.Count - 1; i >= 0; i--)
        {
            if (finalised.Contains(staged[i].Pair.From)) continue;
            try
            {
                File.Move(Path.Combine(directory, staged[i].Temp), Path.Combine(directory, staged[i].Pair.From));
            }
            catch (Exception ex)
            {
                clean = false;
                outcome.Errors.Add($"rollback failed for '{staged[i].Pair.From}': {ex.Message}");
            }
        }

        return clean;
    }

    private static string ReserveTempName(string directory)
    {
        for (var attempt = 0; attempt < 64; attempt++)
        {
            var candidate = "~brs-" + Guid.NewGuid().ToString("N") + ".tmp";
            if (!File.Exists(Path.Combine(directory, candidate)) &&
                !Directory.Exists(Path.Combine(directory, candidate)))
            {
                return candidate;
            }
        }

        throw new IOException("Could not reserve a temporary file name.");
    }

    /// <summary>
    /// Appends a batch to a rolling journal under %LOCALAPPDATA% so a rename remains traceable
    /// after the app closes. Failure to journal never blocks the rename itself.
    /// </summary>
    public static string? TryWriteJournal(RenameBatch batch)
    {
        try
        {
            var folder = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "BatchRenameStudio");
            Directory.CreateDirectory(folder);

            var path = Path.Combine(
                folder,
                $"rename-{batch.TimestampUtc:yyyyMMdd-HHmmss-fff}.json");

            var builder = new StringBuilder();
            builder.Append("{\n");
            builder.Append("  \"timestampUtc\": ")
                   .Append(JsonText.Quote(batch.TimestampUtc.ToString("o")))
                   .Append(",\n");
            builder.Append("  \"directory\": ").Append(JsonText.Quote(batch.Directory)).Append(",\n");
            builder.Append("  \"pairs\": [\n");
            for (var i = 0; i < batch.Pairs.Count; i++)
            {
                builder.Append("    {\"from\": ").Append(JsonText.Quote(batch.Pairs[i].From));
                builder.Append(", \"to\": ").Append(JsonText.Quote(batch.Pairs[i].To)).Append('}');
                builder.Append(i == batch.Pairs.Count - 1 ? "\n" : ",\n");
            }

            builder.Append("  ]\n}\n");

            JsonText.WriteFile(path, builder.ToString());
            return path;
        }
        catch
        {
            return null;
        }
    }
}

