using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Command-line front end.
/// <para>
/// Contract A: <c>--plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</c><br/>
/// Contract B: <c>--explain --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;trace.json&gt;</c>
/// </para>
/// Both exit 0 on success, print exactly one summary line to stdout and never rename anything.
/// </summary>
internal static class HeadlessRunner
{
    public const int ExitSuccess = 0;
    public const int ExitFailure = 2;

    public static bool LooksHeadless(string[] args)
    {
        foreach (var arg in args)
        {
            if (arg.StartsWith("--", StringComparison.Ordinal) || arg.StartsWith("-", StringComparison.Ordinal))
                return true;
        }

        return args.Length > 0;
    }

    public static int Run(string[] args)
    {
        ConsoleBridge.Attach();

        try
        {
            return Dispatch(args);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitFailure;
        }
    }

    private static int Dispatch(string[] args)
    {
        string? mode = null;
        string? dir = null;
        string? rulesPath = null;
        string? outPath = null;

        for (var i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            var (name, inlineValue) = SplitArgument(arg);

            switch (name)
            {
                case "--plan":
                case "--explain":
                case "--selftest":
                    if (mode is not null)
                    {
                        Console.Error.WriteLine($"error: '{name}' conflicts with '{mode}'.");
                        return ExitFailure;
                    }

                    mode = name;
                    break;

                case "--dir":
                    if (!TakeValue(args, ref i, inlineValue, name, out dir)) return ExitFailure;
                    break;

                case "--rules":
                    if (!TakeValue(args, ref i, inlineValue, name, out rulesPath)) return ExitFailure;
                    break;

                case "--out":
                    if (!TakeValue(args, ref i, inlineValue, name, out outPath)) return ExitFailure;
                    break;

                case "--help":
                case "-h":
                case "-?":
                case "/?":
                    PrintUsage(Console.Out);
                    return ExitSuccess;

                case "--version":
                    Console.Out.WriteLine("Batch Rename Studio Pro 1.0.0");
                    return ExitSuccess;

                default:
                    Console.Error.WriteLine($"error: unknown argument '{arg}'.");
                    PrintUsage(Console.Error);
                    return ExitFailure;
            }
        }

        if (mode == "--selftest") return SelfTest.Run() ? ExitSuccess : ExitFailure;

        if (mode is null)
        {
            Console.Error.WriteLine("error: expected --plan, --explain or --selftest.");
            PrintUsage(Console.Error);
            return ExitFailure;
        }

        if (!Require(dir, "--dir") || !Require(rulesPath, "--rules") || !Require(outPath, "--out"))
            return ExitFailure;

        if (!Directory.Exists(dir))
        {
            Console.Error.WriteLine($"error: directory not found: {dir}");
            return ExitFailure;
        }

        if (!File.Exists(rulesPath))
        {
            Console.Error.WriteLine($"error: rules file not found: {rulesPath}");
            return ExitFailure;
        }

        RuleSet rules;
        try
        {
            rules = RuleSet.Load(rulesPath!);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: could not parse rules file: {ex.Message}");
            return ExitFailure;
        }

        var result = RenameEngine.Run(dir!, rules);

        if (mode == "--plan")
        {
            JsonText.WriteFile(outPath!, PlanJson.BuildPlan(result));
            var s = result.Summary;
            Console.Out.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "plan: total={0} ok={1} collision={2} unchanged={3} invalid={4} -> {5}",
                s.Total, s.Ok, s.Collision, s.Unchanged, s.Invalid, Path.GetFullPath(outPath!)));
        }
        else
        {
            JsonText.WriteFile(outPath!, PlanJson.BuildTrace(result));
            Console.Out.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "explain: files={0} steps={1} -> {2}",
                result.Items.Count, rules.Steps.Count, Path.GetFullPath(outPath!)));
        }

        return ExitSuccess;
    }

    private static (string Name, string? Value) SplitArgument(string arg)
    {
        var equals = arg.IndexOf('=');
        if (equals > 0 && arg.StartsWith("--", StringComparison.Ordinal))
            return (arg[..equals], arg[(equals + 1)..]);
        return (arg, null);
    }

    private static bool TakeValue(string[] args, ref int i, string? inlineValue, string name, out string? value)
    {
        if (inlineValue is not null)
        {
            value = inlineValue;
            return true;
        }

        if (i + 1 >= args.Length)
        {
            Console.Error.WriteLine($"error: '{name}' requires a value.");
            value = null;
            return false;
        }

        value = args[++i];
        return true;
    }

    private static bool Require(string? value, string name)
    {
        if (!string.IsNullOrEmpty(value)) return true;
        Console.Error.WriteLine($"error: '{name}' is required.");
        return false;
    }

    private static void PrintUsage(TextWriter writer)
    {
        writer.WriteLine("Batch Rename Studio Pro");
        writer.WriteLine();
        writer.WriteLine("  BatchRenameStudio.exe");
        writer.WriteLine("      Launch the graphical rule editor.");
        writer.WriteLine();
        writer.WriteLine("  BatchRenameStudio.exe --plan    --dir <folder> --rules <rules.json> --out <plan.json>");
        writer.WriteLine("      Write the rename plan. Renames nothing. Exit code 0 on success.");
        writer.WriteLine();
        writer.WriteLine("  BatchRenameStudio.exe --explain --dir <folder> --rules <rules.json> --out <trace.json>");
        writer.WriteLine("      Write the per-step trace. Renames nothing. Exit code 0 on success.");
        writer.WriteLine();
        writer.WriteLine("  BatchRenameStudio.exe --selftest");
        writer.WriteLine("      Run the built-in semantic conformance checks.");
    }
}

