using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Built-in conformance checks for the literal semantics in the specification.
/// Run with <c>BatchRenameStudio.exe --selftest</c>; exit code 0 means every check passed.
/// This lives in the product rather than a separate test project so that the shipped binary can
/// always prove itself on the machine it runs on, with no extra tooling.
/// </summary>
internal static class SelfTest
{
    private static int _passed;
    private static readonly List<string> Failures = new();

    public static bool Run()
    {
        _passed = 0;
        Failures.Clear();

        NameSplitAndReassembly();
        CarriedOverOperations();
        NewOperations();
        StepOrderAndTargetString();
        SequenceCounters();
        TemplateTokens();
        FileSystemSemantics();
        OutputFormats();

        Console.Out.WriteLine();
        foreach (var failure in Failures) Console.Out.WriteLine("FAIL  " + failure);

        Console.Out.WriteLine(
            $"selftest: {_passed} passed, {Failures.Count} failed, {_passed + Failures.Count} total");
        return Failures.Count == 0;
    }

    // ------------------------------------------------------------------ helpers

    private static void Check(string label, string actual, string expected)
    {
        if (string.Equals(actual, expected, StringComparison.Ordinal)) _passed++;
        else Failures.Add($"{label}: expected \"{expected}\" but got \"{actual}\"");
    }

    private static void CheckTrue(string label, bool condition)
    {
        if (condition) _passed++;
        else Failures.Add($"{label}: expected true");
    }

    private static RuleStep Step(string op, params (string Key, object? Value)[] values)
    {
        var step = new RuleStep(op);
        foreach (var (key, value) in values)
        {
            step[key] = value switch
            {
                int i => (long)i,
                _ => value,
            };
        }

        return step;
    }

    private static RuleSet Rules(ApplyTo applyTo, params RuleStep[] steps)
    {
        var ruleSet = new RuleSet { ApplyTo = applyTo };
        ruleSet.Steps.AddRange(steps);
        return ruleSet;
    }

    private static string Proposed(string name, ApplyTo applyTo, params RuleStep[] steps) =>
        RenameEngine.Project(name, Rules(applyTo, steps), 0).Proposed;

    private static string Proposed(string name, ApplyTo applyTo, int index, params RuleStep[] steps) =>
        RenameEngine.Project(name, Rules(applyTo, steps), index).Proposed;

    // ------------------------------------------------------------------ rules 2, 3, 6

    private static void NameSplitAndReassembly()
    {
        var upper = Step("case", ("mode", "upper"));

        Check("rule2 dotfile", Proposed(".gitignore", ApplyTo.Name, upper), ".GITIGNORE");
        Check("rule2 double extension", Proposed("a.tar.gz", ApplyTo.Name, upper), "A.TAR.gz");
        Check("rule2 trailing dot", Proposed("a.", ApplyTo.Name, upper), "A");
        Check("rule2 no extension", Proposed("README", ApplyTo.Name, upper), "README");
        Check("rule3 nameAndExtension", Proposed("a.tar.gz", ApplyTo.NameAndExtension, upper), "A.TAR.GZ");

        var (baseName, ext) = NameRules.Split(".gitignore");
        Check("rule2 split base", baseName, ".gitignore");
        Check("rule2 split ext", ext, string.Empty);
        Check("rule6 join without ext", NameRules.Join("a", string.Empty), "a");
        Check("rule6 join with ext", NameRules.Join("a", "txt"), "a.txt");
    }

    // ------------------------------------------------------------------ the 6 carried-over ops

    private static void CarriedOverOperations()
    {
        Check("replace all occurrences",
            Proposed("aaa.txt", ApplyTo.Name, Step("replace", ("find", "a"), ("replaceWith", "b"))),
            "bbb.txt");

        Check("replace empty find is a no-op",
            Proposed("aaa.txt", ApplyTo.Name, Step("replace", ("find", ""), ("replaceWith", "Z"))),
            "aaa.txt");

        Check("replace ignoreCase",
            Proposed("AbA.txt", ApplyTo.Name,
                Step("replace", ("find", "a"), ("replaceWith", "x"), ("ignoreCase", true))),
            "xbx.txt");

        Check("replace regex with group reference",
            Proposed("img_12.txt", ApplyTo.Name,
                Step("replace", ("find", @"(\d+)"), ("replaceWith", "[$1]"), ("regex", true))),
            "img_[12].txt");

        Check("replace invalid regex stays inert",
            Proposed("a.txt", ApplyTo.Name, Step("replace", ("find", "("), ("regex", true))),
            "a.txt");

        Check("insert prefix",
            Proposed("a.txt", ApplyTo.Name, Step("insert", ("text", "X_"), ("position", "prefix"))),
            "X_a.txt");

        Check("insert suffix",
            Proposed("a.txt", ApplyTo.Name, Step("insert", ("text", "_X"), ("position", "suffix"))),
            "a_X.txt");

        Check("insert at index",
            Proposed("abc.txt", ApplyTo.Name, Step("insert", ("text", "-"), ("position", "index"), ("index", 1))),
            "a-bc.txt");

        Check("insert index clamped high",
            Proposed("abc.txt", ApplyTo.Name, Step("insert", ("text", "!"), ("position", "index"), ("index", 99))),
            "abc!.txt");

        Check("insert index clamped low",
            Proposed("abc.txt", ApplyTo.Name, Step("insert", ("text", "!"), ("position", "index"), ("index", -5))),
            "!abc.txt");

        Check("remove clamps count",
            Proposed("abcdef.txt", ApplyTo.Name, Step("remove", ("from", 1), ("count", 99))),
            "a.txt");

        Check("remove clamps from",
            Proposed("abc.txt", ApplyTo.Name, Step("remove", ("from", 99), ("count", 2))),
            "abc.txt");

        Check("case upper", Proposed("mixed Case.txt", ApplyTo.Name, Step("case", ("mode", "upper"))), "MIXED CASE.txt");
        Check("case lower", Proposed("MIXED Case.txt", ApplyTo.Name, Step("case", ("mode", "lower"))), "mixed case.txt");
        Check("case title", Proposed("hello world-foo.txt", ApplyTo.Name, Step("case", ("mode", "title"))), "Hello World-Foo.txt");
        Check("case title lowers the tail", Proposed("ABC dEF.txt", ApplyTo.Name, Step("case", ("mode", "title"))), "Abc Def.txt");
        Check("case title leaves digits alone", Proposed("a1b2.txt", ApplyTo.Name, Step("case", ("mode", "title"))), "A1B2.txt");

        Check("extension lower", Proposed("a.TXT", ApplyTo.Name, Step("extension", ("mode", "lower"))), "a.txt");
        Check("extension upper", Proposed("a.txt", ApplyTo.Name, Step("extension", ("mode", "upper"))), "a.TXT");
        Check("extension set", Proposed("a.txt", ApplyTo.Name, Step("extension", ("mode", "set"), ("value", "md"))), "a.md");

        Check("extension set gains an extension",
            Proposed("README", ApplyTo.Name, Step("extension", ("mode", "set"), ("value", "md"))),
            "README.md");

        Check("extension under nameAndExtension",
            Proposed("a.TXT", ApplyTo.NameAndExtension, Step("extension", ("mode", "lower"))),
            "a.txt");

        Check("extension set under nameAndExtension on a file with no extension",
            Proposed("README", ApplyTo.NameAndExtension, Step("extension", ("mode", "set"), ("value", "md"))),
            "README.md");
    }

    // ------------------------------------------------------------------ the 8 new ops

    private static void NewOperations()
    {
        Check("pad left", Proposed("ab.txt", ApplyTo.Name, Step("pad", ("length", 5), ("fill", "_"), ("side", "left"))), "___ab.txt");
        Check("pad right", Proposed("ab.txt", ApplyTo.Name, Step("pad", ("length", 5), ("fill", "0"), ("side", "right"))), "ab000.txt");
        Check("pad already long enough", Proposed("abcdef.txt", ApplyTo.Name, Step("pad", ("length", 3), ("fill", "_"))), "abcdef.txt");
        Check("pad rejects a multi-character fill", Proposed("ab.txt", ApplyTo.Name, Step("pad", ("length", 6), ("fill", "xy"))), "ab.txt");
        Check("pad rejects an empty fill", Proposed("ab.txt", ApplyTo.Name, Step("pad", ("length", 6), ("fill", ""))), "ab.txt");

        Check("trim both", Proposed("__a-b__.txt", ApplyTo.Name, Step("trim", ("chars", "_"), ("side", "both"))), "a-b.txt");
        Check("trim left", Proposed("__ab__.txt", ApplyTo.Name, Step("trim", ("chars", "_"), ("side", "left"))), "ab__.txt");
        Check("trim right", Proposed("__ab__.txt", ApplyTo.Name, Step("trim", ("chars", "_"), ("side", "right"))), "__ab.txt");
        Check("trim multi-character set", Proposed(" _-ab-_ .txt", ApplyTo.Name, Step("trim", ("chars", " _-"), ("side", "both"))), "ab.txt");
        Check("trim empty set is a no-op", Proposed("__ab__.txt", ApplyTo.Name, Step("trim", ("chars", ""))), "__ab__.txt");

        Check("slug basic", Proposed("Hello, World! 2024.txt", ApplyTo.Name, Step("slug", ("separator", "-"))), "hello-world-2024.txt");
        Check("slug trims separators", Proposed("  Hi!  .txt", ApplyTo.Name, Step("slug", ("separator", "-"))), "hi.txt");
        Check("slug with an empty separator", Proposed("a b_c.txt", ApplyTo.Name, Step("slug", ("separator", ""))), "abc.txt");
        Check("slug with a '$' separator stays literal", Proposed("a b.txt", ApplyTo.Name, Step("slug", ("separator", "$0"))), "a$0b.txt");

        Check("translate maps characters",
            Proposed("beautiful.txt", ApplyTo.Name, Step("translate", ("from", "aeiou"), ("to", "12345"))),
            "b215t3f5l.txt");

        Check("translate deletes when 'to' is shorter",
            Proposed("abcabc.txt", ApplyTo.Name, Step("translate", ("from", "abc"), ("to", "x"))),
            "xx.txt");

        Check("translate first mapping wins",
            Proposed("aa.txt", ApplyTo.Name, Step("translate", ("from", "aa"), ("to", "12"))),
            "11.txt");

        Check("translate empty 'from' is a no-op",
            Proposed("abc.txt", ApplyTo.Name, Step("translate", ("from", ""), ("to", "xyz"))),
            "abc.txt");

        Check("numberFormat pads the first run",
            Proposed("img12x34.txt", ApplyTo.Name, Step("numberFormat", ("width", 5))),
            "img00012x34.txt");

        Check("numberFormat leaves a long enough run alone",
            Proposed("img123.txt", ApplyTo.Name, Step("numberFormat", ("width", 2))),
            "img123.txt");

        Check("numberFormat without digits",
            Proposed("abc.txt", ApplyTo.Name, Step("numberFormat", ("width", 4))),
            "abc.txt");

        Check("extract whole match",
            Proposed("abc123def456.txt", ApplyTo.Name, Step("extract", ("pattern", @"\d+"), ("group", 0))),
            "123.txt");

        Check("extract a group",
            Proposed("ab12.txt", ApplyTo.Name, Step("extract", ("pattern", @"(\d)(\d)"), ("group", 2))),
            "2.txt");

        Check("extract with no match empties the target",
            Proposed("abc.txt", ApplyTo.Name, Step("extract", ("pattern", @"\d+"))),
            ".txt");

        Check("extract with an out-of-range group empties the target",
            Proposed("ab12.txt", ApplyTo.Name, Step("extract", ("pattern", @"(\d)"), ("group", 7))),
            ".txt");

        Check("dedupeChars collapses runs",
            Proposed("aabbccABBA.txt", ApplyTo.Name, Step("dedupeChars")),
            "abcABA.txt");

        Check("dedupeChars is case sensitive",
            Proposed("aAaA.txt", ApplyTo.Name, Step("dedupeChars")),
            "aAaA.txt");
    }

    // ------------------------------------------------------------------ rules 4 and 6

    private static void StepOrderAndTargetString()
    {
        Check("rule4 steps chain in array order",
            Proposed("a.txt", ApplyTo.Name,
                Step("insert", ("text", "1"), ("position", "suffix")),
                Step("insert", ("text", "2"), ("position", "suffix"))),
            "a12.txt");

        Check("rule6 extension step applies in place under nameAndExtension",
            Proposed("a.txt", ApplyTo.NameAndExtension,
                Step("extension", ("mode", "set"), ("value", "md")),
                Step("insert", ("text", "_x"), ("position", "suffix"))),
            "a.md_x");

        // Under applyTo:"name" the extension step never touches the target string.
        var result = RenameEngine.Project(
            "a.TXT",
            Rules(ApplyTo.Name, Step("extension", ("mode", "lower"))),
            0);

        Check("extension trace before equals after under applyTo=name",
            result.Steps[0].Before,
            result.Steps[0].After);
        Check("extension still changed the extension", result.Proposed, "a.txt");

        // Steps that change nothing still produce a trace entry.
        var inert = RenameEngine.Project(
            "a.txt",
            Rules(ApplyTo.Name,
                Step("replace", ("find", "zzz"), ("replaceWith", "!")),
                Step("case", ("mode", "upper"))),
            0);

        CheckTrue("a no-op step still appears in the trace", inert.Steps.Count == 2);
        Check("no-op trace entry is unchanged", inert.Steps[0].Before, inert.Steps[0].After);
        Check("trace op names are recorded", inert.Steps[1].Op, "case");
        CheckTrue("trace indexes follow the array", inert.Steps[1].Index == 1);
    }

    // ------------------------------------------------------------------ sequence counters

    private static void SequenceCounters()
    {
        var steps = new[]
        {
            Step("sequence", ("pattern", "{n:00}-"), ("start", 1), ("step", 1), ("position", "prefix")),
            Step("sequence", ("pattern", "-{n:000}"), ("start", 10), ("step", 5), ("position", "suffix")),
        };

        Check("two sequence steps keep independent counters (index 0)",
            Proposed("a.txt", ApplyTo.Name, 0, steps), "01-a-010.txt");
        Check("two sequence steps keep independent counters (index 2)",
            Proposed("a.txt", ApplyTo.Name, 2, steps), "03-a-020.txt");

        Check("sequence pattern without a token is literal",
            Proposed("a.txt", ApplyTo.Name, 3, Step("sequence", ("pattern", "x_"), ("position", "prefix"))),
            "x_a.txt");

        Check("sequence pad width shorter than the number",
            Proposed("a.txt", ApplyTo.Name, 0, Step("sequence", ("pattern", "{n:0}_"), ("start", 100))),
            "100_a.txt");

        Check("sequence start may be zero",
            Proposed("a.txt", ApplyTo.Name, 0, Step("sequence", ("pattern", "{n:000}_"), ("start", 0))),
            "000_a.txt");
    }

    // ------------------------------------------------------------------ template tokens

    private static void TemplateTokens()
    {
        Check("template name, ext and sequence",
            Proposed("a.txt", ApplyTo.Name, 0, Step("template", ("format", "{name}-{ext}-{n:000}"))),
            "a-txt-001.txt");

        Check("template n is the processing index plus one",
            Proposed("a.txt", ApplyTo.Name, 4, Step("template", ("format", "{n:00}"))),
            "05.txt");

        Check("template len is the current target length",
            Proposed("abcd.txt", ApplyTo.Name, 0, Step("template", ("format", "{len}"))),
            "4.txt");

        Check("template ext is the ORIGINAL extension",
            Proposed("a.txt", ApplyTo.Name, 0,
                Step("extension", ("mode", "set"), ("value", "md")),
                Step("template", ("format", "{ext}"))),
            "txt.md");

        Check("template leaves unknown tokens literal",
            Proposed("a.txt", ApplyTo.Name, 0, Step("template", ("format", "{foo}-{name}"))),
            "{foo}-a.txt");

        Check("template does not rescan substituted text",
            Proposed("x{ext}.txt", ApplyTo.Name, 0, Step("template", ("format", "{name}!"))),
            "x{ext}!.txt");

        Check("template under nameAndExtension replaces the whole name",
            Proposed("a.txt", ApplyTo.NameAndExtension, 0, Step("template", ("format", "{name}"))),
            "a.txt");
    }

    // ------------------------------------------------------------------ rules 1, 5, 7, 8

    private static void FileSystemSemantics()
    {
        var root = Path.Combine(Path.GetTempPath(), "brs-selftest-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);

        try
        {
            File.WriteAllText(Path.Combine(root, "a.txt"), "a");
            File.WriteAllText(Path.Combine(root, "b.txt"), "b");
            File.WriteAllText(Path.Combine(root, "B0.txt"), "B0");
            Directory.CreateDirectory(Path.Combine(root, "subdir"));
            File.WriteAllText(Path.Combine(root, "subdir", "deep.txt"), "deep");

            var names = RenameEngine.EnumerateFiles(root, SortMode.Name);
            CheckTrue("rule1 directories and nested files are excluded", names.Count == 3);
            Check("rule5 ordinal ascending is case sensitive", string.Join(",", names), "B0.txt,a.txt,b.txt");

            // rule 7: collision against an existing file.
            var collide = RenameEngine.Run(root, Rules(ApplyTo.Name,
                Step("replace", ("find", "a"), ("replaceWith", "b"))));
            var aItem = collide.Items.Find(i => i.Original == "a.txt")!;
            var bItem = collide.Items.Find(i => i.Original == "b.txt")!;
            Check("collision with an existing file", aItem.Status, RenameStatus.Collision);
            Check("untouched file is unchanged", bItem.Status, RenameStatus.Unchanged);

            // rule 7: two items proposing the same name.
            var duplicate = RenameEngine.Run(root, Rules(ApplyTo.Name, Step("template", ("format", "same"))));
            CheckTrue("collision between proposals", duplicate.Items.TrueForAll(i => i.Status == RenameStatus.Collision));
            CheckTrue("summary counts collisions", duplicate.Summary.Collision == 3 && duplicate.Summary.Total == 3);

            // rule 7: invalid characters win over collision.
            var invalidChar = RenameEngine.Run(root, Rules(ApplyTo.Name,
                Step("template", ("format", "x:y"))));
            CheckTrue("illegal character is invalid", invalidChar.Items.TrueForAll(i => i.Status == RenameStatus.Invalid));
            CheckTrue("summary counts invalids", invalidChar.Summary.Invalid == 3);

            // rule 7: reserved device names.
            var reserved = RenameEngine.Run(root, Rules(ApplyTo.Name, Step("template", ("format", "CON"))));
            Check("reserved device name is invalid", reserved.Items[0].Status, RenameStatus.Invalid);

            var lpt = RenameEngine.Run(root, Rules(ApplyTo.Name, Step("template", ("format", "lpt9"))));
            Check("reserved name test is case insensitive", lpt.Items[0].Status, RenameStatus.Invalid);

            // rule 7: empty proposal.
            var empty = RenameEngine.Run(root, Rules(ApplyTo.NameAndExtension,
                Step("extract", ("pattern", "zzz"))));
            Check("empty proposal is invalid", empty.Items[0].Status, RenameStatus.Invalid);

            // rule 7: over-long proposal.
            var tooLong = RenameEngine.Run(root, Rules(ApplyTo.Name,
                Step("pad", ("length", 300), ("fill", "x"), ("side", "right"))));
            Check("over-long proposal is invalid", tooLong.Items[0].Status, RenameStatus.Invalid);

            // rule 7: ordinary success.
            var ok = RenameEngine.Run(root, Rules(ApplyTo.Name,
                Step("sequence", ("pattern", "{n:000}_"), ("start", 1), ("step", 1))));
            Check("plain sequence renames every file", string.Join(",", ok.Items.ConvertAll(i => i.Proposed)),
                "001_B0.txt,002_a.txt,003_b.txt");
            CheckTrue("summary counts ok", ok.Summary.Ok == 3);

            // rules 1 and "renames nothing".
            var after = RenameEngine.EnumerateFiles(root, SortMode.Name);
            Check("planning renames nothing", string.Join(",", after), "B0.txt,a.txt,b.txt");

            // rule 5: created/modified ordering with a deterministic tie-break.
            var byModified = RenameEngine.EnumerateFiles(root, SortMode.Modified);
            CheckTrue("modified ordering returns every file", byModified.Count == 3);

            // rule 9: byte-identical output for identical input.
            var first = PlanJson.BuildPlan(RenameEngine.Run(root, Rules(ApplyTo.Name, Step("case", ("mode", "upper")))));
            var second = PlanJson.BuildPlan(RenameEngine.Run(root, Rules(ApplyTo.Name, Step("case", ("mode", "upper")))));
            Check("rule9 determinism", first, second);

            // The two-phase executor must handle a straight swap.
            var swap = RenameExecutor.Execute(root, new[]
            {
                new RenamePair("a.txt", "b.txt"),
                new RenamePair("b.txt", "a.txt"),
            });
            CheckTrue("two-phase swap succeeds", swap.Succeeded && swap.Renamed == 2);
            Check("swap moved the contents", File.ReadAllText(Path.Combine(root, "a.txt")), "b");

            if (swap.Batch is not null)
            {
                var undo = RenameExecutor.Undo(swap.Batch);
                CheckTrue("undo succeeds", undo.Succeeded);
                Check("undo restored the contents", File.ReadAllText(Path.Combine(root, "a.txt")), "a");
            }
        }
        finally
        {
            try { Directory.Delete(root, recursive: true); } catch { /* best effort */ }
        }
    }

    // ------------------------------------------------------------------ output contracts

    private static void OutputFormats()
    {
        var root = Path.Combine(Path.GetTempPath(), "brs-selftest-out-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);

        try
        {
            File.WriteAllText(Path.Combine(root, "a.txt"), "a");

            var rules = Rules(ApplyTo.Name,
                Step("extension", ("mode", "lower")),
                Step("case", ("mode", "upper")));

            var result = RenameEngine.Run(root, rules);

            var plan = PlanJson.BuildPlan(result);
            CheckTrue("plan carries the schema version", plan.Contains("\"schemaVersion\": 1", StringComparison.Ordinal));
            CheckTrue("plan carries the summary", plan.Contains("\"summary\"", StringComparison.Ordinal));
            CheckTrue("plan has no CR characters", !plan.Contains('\r'));

            var trace = PlanJson.BuildTrace(result);
            CheckTrue("trace lists one entry per step", CountOccurrences(trace, "\"index\":") == rules.Steps.Count);
            CheckTrue("trace carries the status", trace.Contains("\"status\": \"ok\"", StringComparison.Ordinal));

            var planPath = Path.Combine(root, "plan.json");
            JsonText.WriteFile(planPath, plan);
            var bytes = File.ReadAllBytes(planPath);
            CheckTrue("plan.json has no UTF-8 BOM",
                bytes.Length < 3 || !(bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF));

            var reparsed = Encoding.UTF8.GetString(bytes);
            Check("plan.json round-trips", reparsed, plan);

            using var document = System.Text.Json.JsonDocument.Parse(reparsed);
            CheckTrue("plan.json is valid JSON",
                document.RootElement.GetProperty("summary").GetProperty("total").GetInt32() == 1);

            using var traceDocument = System.Text.Json.JsonDocument.Parse(trace);
            CheckTrue("trace.json is valid JSON",
                traceDocument.RootElement.GetProperty("files").GetArrayLength() == 1);

            // An empty folder must still emit well-formed documents.
            var emptyDir = Path.Combine(root, "empty");
            Directory.CreateDirectory(emptyDir);
            var emptyResult = RenameEngine.Run(emptyDir, rules);
            using var emptyPlan = System.Text.Json.JsonDocument.Parse(PlanJson.BuildPlan(emptyResult));
            CheckTrue("empty folder yields an empty item list",
                emptyPlan.RootElement.GetProperty("items").GetArrayLength() == 0);
            using var emptyTrace = System.Text.Json.JsonDocument.Parse(PlanJson.BuildTrace(emptyResult));
            CheckTrue("empty folder yields an empty file list",
                emptyTrace.RootElement.GetProperty("files").GetArrayLength() == 0);

            // rules.json round-trip through the serializer used by the GUI.
            var saved = rules.ToJson();
            var reloaded = RuleSet.Parse(saved);
            CheckTrue("rules round-trip keeps the step count", reloaded.Steps.Count == rules.Steps.Count);
            Check("rules round-trip keeps the result",
                RenameEngine.Project("a.TXT", reloaded, 0).Proposed,
                RenameEngine.Project("a.TXT", rules, 0).Proposed);
        }
        finally
        {
            try { Directory.Delete(root, recursive: true); } catch { /* best effort */ }
        }
    }

    private static int CountOccurrences(string haystack, string needle)
    {
        var count = 0;
        var index = 0;
        while ((index = haystack.IndexOf(needle, index, StringComparison.Ordinal)) >= 0)
        {
            count++;
            index += needle.Length;
        }

        return count;
    }
}

