                combo.SelectedIndexChanged += (_, _) => Commit(field.Key, combo.SelectedItem as string ?? string.Empty);
                return combo;
            }

            default:
            {
                var text = new TextBox
                {
                    Width = 260,
                    Margin = new Padding(0, 4, 0, 4),
                    Text = step.GetString(field.Key, field.Default as string ?? string.Empty),
                };
                text.TextChanged += (_, _) => Commit(field.Key, text.Text);
                return text;
            }
        }
    }

    private void Commit(string key, object? value)
    {
        if (_suspendEvents || _step is null) return;
        _step[key] = value;
        StepEdited?.Invoke(this, EventArgs.Empty);
    }
}

