namespace BatchRenameStudio.Ui;

/// <summary>Shared colours so the status vocabulary reads the same everywhere in the GUI.</summary>
public static class AppTheme
{
    public static readonly Color WindowBackground = Color.FromArgb(0xF6, 0xF7, 0xF9);
    public static readonly Color PanelBackground = Color.White;
    public static readonly Color MutedText = Color.FromArgb(0x6B, 0x72, 0x80);
    public static readonly Color Divider = Color.FromArgb(0xE2, 0xE5, 0xEA);

    public static readonly Color OkBackground = Color.FromArgb(0xE9, 0xF7, 0xEE);
    public static readonly Color OkText = Color.FromArgb(0x1B, 0x5E, 0x20);

    public static readonly Color CollisionBackground = Color.FromArgb(0xFD, 0xF1, 0xE0);
    public static readonly Color CollisionText = Color.FromArgb(0x8A, 0x4B, 0x08);

    public static readonly Color InvalidBackground = Color.FromArgb(0xFD, 0xEC, 0xEC);
    public static readonly Color InvalidText = Color.FromArgb(0x8E, 0x1B, 0x1B);

    public static readonly Color UnchangedBackground = Color.FromArgb(0xF3, 0xF4, 0xF6);
    public static readonly Color UnchangedText = Color.FromArgb(0x6B, 0x72, 0x80);

    public static (Color Back, Color Fore) ForStatus(string status) => status switch
    {
        Core.RenameStatus.Ok => (OkBackground, OkText),
        Core.RenameStatus.Collision => (CollisionBackground, CollisionText),
        Core.RenameStatus.Invalid => (InvalidBackground, InvalidText),
        _ => (UnchangedBackground, UnchangedText),
    };

    public static string StatusLabel(string status) => status switch
    {
        Core.RenameStatus.Ok => "ok・可更名",
        Core.RenameStatus.Collision => "collision・名稱衝突",
        Core.RenameStatus.Invalid => "invalid・名稱不合法",
        Core.RenameStatus.Unchanged => "unchanged・未變更",
        _ => status,
    };
}

