using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The rule editor window.
/// <para>
/// The preview, the trace pane and the rename itself are all driven by <see cref="RenameEngine"/>,
/// the same code path the <c>--plan</c> and <c>--explain</c> contracts use, so what the window shows
/// is by construction what a headless run would produce.
/// </para>
/// </summary>
public sealed class MainForm : Form
{
    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToCombo = new();
    private readonly ComboBox _sortCombo = new();
    private readonly ComboBox _filterCombo = new();
    private readonly ListBox _ruleList = new();
    private readonly RuleEditorPanel _editor = new();
    private readonly DataGridView _previewGrid = new();
    private readonly DataGridView _traceGrid = new();
    private readonly Label _summaryLabel = new();
    private readonly Label _statusLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly System.Windows.Forms.Timer _debounce = new();
    private readonly ContextMenuStrip _addMenu = new();
    private readonly Stack<RenameBatch> _undoStack = new();

    private SplitContainer _mainSplit = null!;
    private SplitContainer _resultSplit = null!;

    private RuleSet _rules = new();
    private PlanResult? _plan;
    private List<FileResult> _view = new();
    private List<string> _names = new();
    private bool _updatingUi;

    public MainForm()
    {
        BuildUi();
        WireEvents();
        SyncRuleList(-1);
        UpdateStatus("請先選擇要處理的資料夾。");
        UpdateButtons();
    }

    // ================================================================= layout

    private void BuildUi()
    {
        Text = "Batch Rename Studio Pro";
        Font = SystemFonts.MessageBoxFont ?? new Font("Segoe UI", 9f);
        BackColor = AppTheme.WindowBackground;
        ClientSize = new Size(1260, 820);
        MinimumSize = new Size(1040, 680);
        StartPosition = FormStartPosition.CenterScreen;
        KeyPreview = true;

        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 4,
            Padding = new Padding(10),
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildHeader(), 0, 0);
        root.Controls.Add(BuildBody(), 0, 1);
        root.Controls.Add(BuildActionBar(), 0, 2);
        root.Controls.Add(BuildStatusBar(), 0, 3);

        Controls.Add(root);
    }

    private Control BuildHeader()
    {
        var header = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 9,
            RowCount = 1,
            BackColor = AppTheme.PanelBackground,
            Padding = new Padding(12, 10, 12, 10),
            Margin = new Padding(0, 0, 0, 8),
        };

        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
        for (var i = 0; i < 7; i++) header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        header.Controls.Add(FieldLabel("資料夾"), 0, 0);

        _folderBox.Anchor = AnchorStyles.Left | AnchorStyles.Right;
        _folderBox.Margin = new Padding(0, 3, 8, 3);
        _folderBox.PlaceholderText = @"例如 D:\Photos\2026";
        header.Controls.Add(_folderBox, 1, 0);

        header.Controls.Add(SmallButton("瀏覽…", 78, BrowseFolder), 2, 0);
        header.Controls.Add(SmallButton("重新整理 (F5)", 118, (_, _) => RefreshPreview()), 3, 0);

        header.Controls.Add(FieldLabel("套用範圍"), 4, 0);
        _applyToCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToCombo.Width = 168;
        _applyToCombo.Margin = new Padding(0, 3, 12, 3);
        _applyToCombo.Items.AddRange(new object[] { "name（僅主檔名）", "nameAndExtension（含副檔名）" });
        _applyToCombo.SelectedIndex = 0;
        header.Controls.Add(_applyToCombo, 5, 0);

        header.Controls.Add(FieldLabel("排序"), 6, 0);
        _sortCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortCombo.Width = 150;
        _sortCombo.Margin = new Padding(0, 3, 0, 3);
        _sortCombo.Items.AddRange(new object[] { "name（序數）", "created（建立時間）", "modified（修改時間）" });
        _sortCombo.SelectedIndex = 0;
        header.Controls.Add(_sortCombo, 7, 0);

        return header;
    }

    private Control BuildBody()
    {
        _mainSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterWidth = 8,
            Panel1MinSize = 360,
            Panel2MinSize = 420,
            BackColor = AppTheme.WindowBackground,
        };

        _mainSplit.Panel1.Controls.Add(BuildRulesPanel());
        _mainSplit.Panel2.Controls.Add(BuildResultsPanel());
        return _mainSplit;
    }

    private Control BuildRulesPanel()
    {
        var panel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 4,
            BackColor = AppTheme.PanelBackground,
            Padding = new Padding(10),
        };
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.Percent, 42f));
        panel.RowStyles.Add(new RowStyle(SizeType.Percent, 58f));

        panel.Controls.Add(SectionTitle("規則鏈（由上而下依序套用）"), 0, 0);

        var toolbar = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            WrapContents = true,
            Margin = new Padding(0, 4, 0, 6),
        };
        toolbar.Controls.Add(SmallButton("新增規則 ▾", 106, ShowAddMenu));
        toolbar.Controls.Add(SmallButton("複製", 60, (_, _) => DuplicateRule()));
        toolbar.Controls.Add(SmallButton("移除", 60, (_, _) => RemoveRule()));
        toolbar.Controls.Add(SmallButton("上移", 60, (_, _) => MoveRule(-1)));
        toolbar.Controls.Add(SmallButton("下移", 60, (_, _) => MoveRule(1)));
        toolbar.Controls.Add(SmallButton("清空", 60, (_, _) => ClearRules()));
        panel.Controls.Add(toolbar, 0, 1);

        _ruleList.Dock = DockStyle.Fill;
        _ruleList.IntegralHeight = false;
        _ruleList.HorizontalScrollbar = true;
        _ruleList.Margin = new Padding(0, 0, 0, 8);
        panel.Controls.Add(_ruleList, 0, 2);

        _editor.Dock = DockStyle.Fill;
        _editor.BorderStyle = BorderStyle.FixedSingle;
        panel.Controls.Add(_editor, 0, 3);

        foreach (var info in OpCatalog.All)
        {
            var item = new ToolStripMenuItem(info.Title) { Tag = info.Op, ToolTipText = info.Summary };
            item.Click += (_, _) => AddRule((string)item.Tag!);
            _addMenu.Items.Add(item);
        }

        return panel;
    }

    private Control BuildResultsPanel()
    {
        _resultSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Horizontal,
            SplitterWidth = 8,
            Panel1MinSize = 220,
            Panel2MinSize = 150,
            BackColor = AppTheme.WindowBackground,
        };

        // ---- preview
        var previewPanel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            RowCount = 3,
            BackColor = AppTheme.PanelBackground,
            Padding = new Padding(10),
        };
        previewPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
        previewPanel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        previewPanel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        previewPanel.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
        previewPanel.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        previewPanel.Controls.Add(SectionTitle("預覽（不會動到檔案）"), 0, 0);

        _filterCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _filterCombo.Width = 150;
        _filterCombo.Margin = new Padding(0, 0, 0, 6);
        _filterCombo.Items.AddRange(new object[] { "顯示全部", "只顯示會更名", "只顯示有問題" });
        _filterCombo.SelectedIndex = 0;
        previewPanel.Controls.Add(_filterCombo, 1, 0);

        ConfigureGrid(_previewGrid);
        _previewGrid.VirtualMode = true;
        AddColumn(_previewGrid, "#", 44, false);
        AddColumn(_previewGrid, "原始名稱", 200, true);
        AddColumn(_previewGrid, "建議名稱", 200, true);
        AddColumn(_previewGrid, "狀態", 132, false);
        AddColumn(_previewGrid, "說明", 180, true);
        previewPanel.Controls.Add(_previewGrid, 0, 1);
        previewPanel.SetColumnSpan(_previewGrid, 2);

        _summaryLabel.AutoSize = true;
        _summaryLabel.ForeColor = AppTheme.MutedText;
        _summaryLabel.Margin = new Padding(0, 6, 0, 0);
        _summaryLabel.Text = "—";
        previewPanel.Controls.Add(_summaryLabel, 0, 2);
        previewPanel.SetColumnSpan(_summaryLabel, 2);

        _resultSplit.Panel1.Controls.Add(previewPanel);

        // ---- trace
        var tracePanel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 2,
            BackColor = AppTheme.PanelBackground,
            Padding = new Padding(10),
        };
        tracePanel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        tracePanel.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));

        tracePanel.Controls.Add(SectionTitle("逐步追蹤（選取上方任一列即可查看）"), 0, 0);

        ConfigureGrid(_traceGrid);
        AddColumn(_traceGrid, "#", 44, false);
        AddColumn(_traceGrid, "op", 120, false);
        AddColumn(_traceGrid, "before", 220, true);
        AddColumn(_traceGrid, "after", 220, true);
        tracePanel.Controls.Add(_traceGrid, 0, 1);

        _resultSplit.Panel2.Controls.Add(tracePanel);
        return _resultSplit;
    }

    private Control BuildActionBar()
    {
        var bar = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            WrapContents = true,
            Margin = new Padding(0, 8, 0, 0),
        };

        _applyButton.Text = "執行更名";
        _applyButton.Width = 120;
        _applyButton.Height = 32;
        _applyButton.Font = new Font(Font, FontStyle.Bold);
        _applyButton.Margin = new Padding(0, 0, 8, 0);
        _applyButton.Click += (_, _) => ApplyRename();
        bar.Controls.Add(_applyButton);

        _undoButton.Text = "復原上一批 (Ctrl+Z)";
        _undoButton.Width = 150;
        _undoButton.Height = 32;
        _undoButton.Margin = new Padding(0, 0, 24, 0);
        _undoButton.Click += (_, _) => UndoRename();
        bar.Controls.Add(_undoButton);

        bar.Controls.Add(ActionButton("匯出 plan.json", 128, (_, _) => ExportPlan()));
        bar.Controls.Add(ActionButton("匯出 trace.json", 128, (_, _) => ExportTrace()));
        bar.Controls.Add(ActionButton("載入規則…", 104, (_, _) => LoadRules()));
        bar.Controls.Add(ActionButton("儲存規則…", 104, (_, _) => SaveRules()));
        bar.Controls.Add(ActionButton("檢視規則 JSON", 128, (_, _) => ShowRulesJson()));

        return bar;
    }

    private Control BuildStatusBar()
    {
        _statusLabel.Dock = DockStyle.Fill;
        _statusLabel.AutoSize = false;
        _statusLabel.Height = 26;
        _statusLabel.TextAlign = ContentAlignment.MiddleLeft;
        _statusLabel.Padding = new Padding(8, 0, 8, 0);
        _statusLabel.BackColor = AppTheme.PanelBackground;
        _statusLabel.ForeColor = AppTheme.MutedText;
        _statusLabel.Margin = new Padding(0, 8, 0, 0);
        return _statusLabel;
    }

    private static Label FieldLabel(string text) => new()
    {
        Text = text,
        AutoSize = true,
        Anchor = AnchorStyles.Left,
        Margin = new Padding(0, 7, 8, 0),
    };

    private static Label SectionTitle(string text) => new()
    {
        Text = text,
        AutoSize = true,
        Font = new Font(SystemFonts.MessageBoxFont ?? new Font("Segoe UI", 9f), FontStyle.Bold),
        Margin = new Padding(0, 0, 0, 6),
    };

    private static Button SmallButton(string text, int width, EventHandler onClick)
    {
        var button = new Button
        {
            Text = text,
            Width = width,
            Height = 27,
            Margin = new Padding(0, 3, 6, 3),
        };
        button.Click += onClick;
        return button;
    }

    private static Button ActionButton(string text, int width, EventHandler onClick)
    {
        var button = new Button
        {
            Text = text,
            Width = width,
            Height = 32,
            Margin = new Padding(0, 0, 8, 0),
        };
        button.Click += onClick;
        return button;
    }

    private static void ConfigureGrid(DataGridView grid)
    {
        grid.Dock = DockStyle.Fill;
        grid.ReadOnly = true;
        grid.AllowUserToAddRows = false;
        grid.AllowUserToDeleteRows = false;
        grid.AllowUserToResizeRows = false;
        grid.RowHeadersVisible = false;
        grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        grid.MultiSelect = false;
        grid.BackgroundColor = Color.White;
        grid.BorderStyle = BorderStyle.FixedSingle;
        grid.EnableHeadersVisualStyles = false;
        grid.ColumnHeadersDefaultCellStyle.BackColor = AppTheme.WindowBackground;
        grid.ColumnHeadersDefaultCellStyle.Font = new Font(SystemFonts.MessageBoxFont ?? new Font("Segoe UI", 9f), FontStyle.Bold);
        grid.ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.DisableResizing;
        grid.ColumnHeadersHeight = 28;
        grid.GridColor = AppTheme.Divider;
        grid.RowTemplate.Height = 22;
    }

    private static void AddColumn(DataGridView grid, string header, int width, bool fill)
    {
        var column = new DataGridViewTextBoxColumn
        {
            HeaderText = header,
            Width = width,
            SortMode = DataGridViewColumnSortMode.NotSortable,
            AutoSizeMode = fill ? DataGridViewAutoSizeColumnMode.Fill : DataGridViewAutoSizeColumnMode.None,
            FillWeight = Math.Max(width, 1),
        };
        grid.Columns.Add(column);
    }

    // ================================================================= events

    private void WireEvents()
    {
        _debounce.Interval = 160;
        _debounce.Tick += (_, _) =>
        {
            _debounce.Stop();
            RefreshPreview();
        };

        _folderBox.TextChanged += (_, _) => ScheduleRefresh();

        _applyToCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToCombo.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            ScheduleRefresh();
        };

        _sortCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = _sortCombo.SelectedIndex switch
            {
                1 => SortMode.Created,
                2 => SortMode.Modified,
                _ => SortMode.Name,
            };
            ScheduleRefresh();
        };

        _filterCombo.SelectedIndexChanged += (_, _) => BindPreview();

        _ruleList.SelectedIndexChanged += (_, _) =>
        {
            if (_updatingUi) return;
            var index = _ruleList.SelectedIndex;
            _editor.Bind(index >= 0 && index < _rules.Steps.Count ? _rules.Steps[index] : null);
        };

        _editor.StepEdited += (_, _) =>
        {
            var index = _ruleList.SelectedIndex;
            if (index >= 0 && index < _rules.Steps.Count) UpdateRuleListEntry(index);
            ScheduleRefresh();
        };

        _previewGrid.CellValueNeeded += OnPreviewCellValueNeeded;
        _previewGrid.CellFormatting += OnPreviewCellFormatting;
        _previewGrid.SelectionChanged += (_, _) => ShowTraceForSelection();

        _traceGrid.CellFormatting += OnTraceCellFormatting;

        KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.F5)
            {
                RefreshPreview();
                e.Handled = true;
            }
            else if (e.Control && e.KeyCode == Keys.Z)
            {
                UndoRename();
                e.Handled = true;
            }
        };
    }

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);
        TrySetSplitter(_mainSplit, 430);
        TrySetSplitter(_resultSplit, (int)(_resultSplit.Height * 0.6));
    }

    private static void TrySetSplitter(SplitContainer split, int distance)
    {
        try
        {
            var max = (split.Orientation == Orientation.Vertical ? split.Width : split.Height)
                      - split.Panel2MinSize - split.SplitterWidth;
            if (max > split.Panel1MinSize)
                split.SplitterDistance = Math.Clamp(distance, split.Panel1MinSize, max);
        }
        catch (InvalidOperationException)
        {
            // The container is too small to honour the requested split; the default is fine.
        }
    }

    private void ScheduleRefresh()
    {
        _debounce.Stop();
        _debounce.Start();
    }

    // ================================================================= rules

    private void ShowAddMenu(object? sender, EventArgs e)
    {
        if (sender is Control control) _addMenu.Show(control, new Point(0, control.Height));
    }

    private void AddRule(string op)
    {
        var step = OpCatalog.CreateStep(op);
        var insertAt = _ruleList.SelectedIndex >= 0 ? _ruleList.SelectedIndex + 1 : _rules.Steps.Count;
        _rules.Steps.Insert(insertAt, step);
        SyncRuleList(insertAt);
        ScheduleRefresh();
    }

    private void DuplicateRule()
    {
        var index = _ruleList.SelectedIndex;
        if (index < 0 || index >= _rules.Steps.Count) return;
        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        SyncRuleList(index + 1);
        ScheduleRefresh();
    }

    private void RemoveRule()
    {
        var index = _ruleList.SelectedIndex;
        if (index < 0 || index >= _rules.Steps.Count) return;
        _rules.Steps.RemoveAt(index);
        SyncRuleList(Math.Min(index, _rules.Steps.Count - 1));
        ScheduleRefresh();
    }

    private void MoveRule(int delta)
    {
        var index = _ruleList.SelectedIndex;
        var target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count) return;

        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        SyncRuleList(target);
        ScheduleRefresh();
    }

    private void ClearRules()
    {
        if (_rules.Steps.Count == 0) return;
        if (MessageBox.Show(this, "確定要清空所有規則？", "Batch Rename Studio Pro",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }

        _rules.Steps.Clear();
        SyncRuleList(-1);
        ScheduleRefresh();
    }

    private void SyncRuleList(int selectIndex)
    {
        _updatingUi = true;
        _ruleList.BeginUpdate();
        _ruleList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
            _ruleList.Items.Add($"{i + 1}. {OpCatalog.Describe(_rules.Steps[i])}");
        _ruleList.EndUpdate();
        _updatingUi = false;

        if (selectIndex >= 0 && selectIndex < _ruleList.Items.Count) _ruleList.SelectedIndex = selectIndex;
        else _editor.Bind(null);
    }

    private void UpdateRuleListEntry(int index)
    {
        _updatingUi = true;
        _ruleList.Items[index] = $"{index + 1}. {OpCatalog.Describe(_rules.Steps[index])}";
        _ruleList.SelectedIndex = index;
        _updatingUi = false;
    }

    // ================================================================= preview

    private void BrowseFolder(object? sender, EventArgs e)
    {
        using var dialog = new FolderBrowserDialog
        {
            Description = "選擇要批次更名的資料夾",
            UseDescriptionForTitle = true,
            ShowNewFolderButton = false,
        };

        if (Directory.Exists(_folderBox.Text)) dialog.SelectedPath = _folderBox.Text;
        if (dialog.ShowDialog(this) == DialogResult.OK) _folderBox.Text = dialog.SelectedPath;
    }

    private void RefreshPreview()
    {
        _debounce.Stop();

        var directory = _folderBox.Text.Trim().Trim('"');
        if (directory.Length == 0)
        {
            _plan = null;
            BindPreview();
            UpdateStatus("請先選擇要處理的資料夾。");
            UpdateButtons();
            return;
        }

        if (!Directory.Exists(directory))
        {
            _plan = null;
            BindPreview();
            UpdateStatus($"找不到資料夾：{directory}");
            UpdateButtons();
            return;
        }

        try
        {
            _names = RenameEngine.EnumerateFiles(directory, _rules.Sort);
            _plan = RenameEngine.Run(directory, _rules, _names);
            UpdateStatus($"已讀取 {_names.Count} 個檔案，規則 {_rules.Steps.Count} 條。");
        }
        catch (Exception ex)
        {
            _plan = null;
            UpdateStatus("讀取失敗：" + ex.Message);
        }

        BindPreview();
        UpdateButtons();
    }

    private void BindPreview()
    {
        _updatingUi = true;
        _previewGrid.RowCount = 0;
        _traceGrid.Rows.Clear();

        _view = _plan is null
            ? new List<FileResult>()
            : _plan.Items.FindAll(item => _filterCombo.SelectedIndex switch
            {
                1 => item.Status == RenameStatus.Ok,
                2 => item.Status is RenameStatus.Collision or RenameStatus.Invalid,
                _ => true,
            });

        _previewGrid.RowCount = _view.Count;
        _updatingUi = false;

        if (_plan is null)
        {
            _summaryLabel.Text = "—";
        }
        else
        {
            var s = _plan.Summary;
            _summaryLabel.Text =
                $"總計 {s.Total}　·　可更名 {s.Ok}　·　衝突 {s.Collision}　·　未變更 {s.Unchanged}　·　不合法 {s.Invalid}" +
                (_view.Count == s.Total ? "" : $"　（目前顯示 {_view.Count} 筆）");
        }

        if (_view.Count > 0)
        {
            _previewGrid.CurrentCell = _previewGrid.Rows[0].Cells[1];
            ShowTraceForSelection();
        }

        _previewGrid.Invalidate();
    }

    private void OnPreviewCellValueNeeded(object? sender, DataGridViewCellValueEventArgs e)
    {
        if (e.RowIndex < 0 || e.RowIndex >= _view.Count) return;
        var item = _view[e.RowIndex];

        e.Value = e.ColumnIndex switch
        {
            0 => (e.RowIndex + 1).ToString(),
            1 => item.Original,
            2 => item.Proposed,
            3 => AppTheme.StatusLabel(item.Status),
            4 => item.Reason,
            _ => string.Empty,
        };
    }

    private void OnPreviewCellFormatting(object? sender, DataGridViewCellFormattingEventArgs e)
    {
        if (e.RowIndex < 0 || e.RowIndex >= _view.Count) return;
        var (back, fore) = AppTheme.ForStatus(_view[e.RowIndex].Status);
        e.CellStyle.BackColor = back;
        e.CellStyle.ForeColor = fore;
        e.CellStyle.SelectionBackColor = ControlPaint.Dark(back, 0.08f);
        e.CellStyle.SelectionForeColor = fore;
    }

    private void ShowTraceForSelection()
    {
        if (_updatingUi) return;

        _traceGrid.Rows.Clear();
        var index = _previewGrid.CurrentCell?.RowIndex ?? -1;
        if (index < 0 || index >= _view.Count) return;

        var item = _view[index];
        foreach (var step in item.Steps)
            _traceGrid.Rows.Add(step.Index.ToString(), step.Op, step.Before, step.After);

        _traceGrid.Rows.Add(string.Empty, "→ proposed", item.Original, item.Proposed);
    }

    private void OnTraceCellFormatting(object? sender, DataGridViewCellFormattingEventArgs e)
    {
        if (e.RowIndex < 0 || e.RowIndex >= _traceGrid.Rows.Count) return;
        var row = _traceGrid.Rows[e.RowIndex];

        if (row.Cells[1].Value as string == "→ proposed")
        {
            e.CellStyle.BackColor = AppTheme.WindowBackground;
            e.CellStyle.Font = new Font(_traceGrid.Font, FontStyle.Bold);
            return;
        }

        var before = row.Cells[2].Value as string ?? string.Empty;
        var after = row.Cells[3].Value as string ?? string.Empty;
        if (string.Equals(before, after, StringComparison.Ordinal)) e.CellStyle.ForeColor = AppTheme.MutedText;
    }

    private void UpdateStatus(string message) => _statusLabel.Text = message;

    private void UpdateButtons()
    {
        _applyButton.Enabled = _plan is not null && _plan.Summary.Ok > 0;
        _undoButton.Enabled = _undoStack.Count > 0;
    }

    // ================================================================= actions

    private void ApplyRename()
    {
        if (_plan is null) return;

        var pending = _plan.Items.FindAll(item => item.Status == RenameStatus.Ok);
        if (pending.Count == 0)
        {
            MessageBox.Show(this, "目前沒有狀態為 ok 的項目可以更名。", "Batch Rename Studio Pro",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var s = _plan.Summary;
        var warning = s.Collision + s.Invalid > 0
            ? $"\n\n另有 {s.Collision} 筆衝突、{s.Invalid} 筆不合法，這些項目會被略過。"
            : string.Empty;

        var confirm = MessageBox.Show(
            this,
            $"即將在\n{_plan.Directory}\n更名 {pending.Count} 個檔案。{warning}\n\n要繼續嗎？",
            "確認更名",
            MessageBoxButtons.YesNo,
            MessageBoxIcon.Warning);

        if (confirm != DialogResult.Yes) return;

        var pairs = pending.ConvertAll(item => new RenamePair(item.Original, item.Proposed));

        Cursor = Cursors.WaitCursor;
        RenameOutcome outcome;
        try
        {
            outcome = RenameExecutor.Execute(_plan.Directory, pairs);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        if (outcome.Succeeded && outcome.Batch is not null)
        {
            _undoStack.Push(outcome.Batch);
            var journal = RenameExecutor.TryWriteJournal(outcome.Batch);
            UpdateStatus($"已更名 {outcome.Renamed} 個檔案。" + (journal is null ? "" : $" 紀錄：{journal}"));
        }
        else
        {
            var rollback = outcome.RolledBack ? "已完整回復原狀。" : "回復時也發生錯誤，請檢查資料夾內容。";
            MessageBox.Show(
                this,
                $"更名失敗，{rollback}\n\n{string.Join(Environment.NewLine, outcome.Errors)}",
                "Batch Rename Studio Pro",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error);
            UpdateStatus("更名失敗：" + outcome.Errors[0]);
        }

        RefreshPreview();
    }

    private void UndoRename()
    {
        if (_undoStack.Count == 0) return;

        var batch = _undoStack.Peek();
        var confirm = MessageBox.Show(
            this,
            $"要復原上一批 {batch.Pairs.Count} 個檔案的更名嗎？\n{batch.Directory}",
            "確認復原",
            MessageBoxButtons.YesNo,
            MessageBoxIcon.Question);

        if (confirm != DialogResult.Yes) return;

        var outcome = RenameExecutor.Undo(batch);
        if (outcome.Succeeded)
        {
            _undoStack.Pop();
            UpdateStatus($"已復原 {outcome.Renamed} 個檔案。");
        }
        else
        {
            MessageBox.Show(
                this,
                "復原失敗：\n" + string.Join(Environment.NewLine, outcome.Errors),
                "Batch Rename Studio Pro",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error);
        }

        RefreshPreview();
    }

    private void ExportPlan() => ExportJson("plan.json", () => PlanJson.BuildPlan(_plan!));

    private void ExportTrace() => ExportJson("trace.json", () => PlanJson.BuildTrace(_plan!));

    private void ExportJson(string defaultName, Func<string> build)
    {
        if (_plan is null)
        {
            MessageBox.Show(this, "請先選擇資料夾並產生預覽。", "Batch Rename Studio Pro",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "匯出",
            FileName = defaultName,
            Filter = "JSON (*.json)|*.json|所有檔案 (*.*)|*.*",
            InitialDirectory = _plan.Directory,
        };

        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            JsonText.WriteFile(dialog.FileName, build());
            UpdateStatus("已匯出：" + dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, "匯出失敗：" + ex.Message, "Batch Rename Studio Pro",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "載入規則",
            Filter = "JSON (*.json)|*.json|所有檔案 (*.*)|*.*",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            _rules = RuleSet.Load(dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, "無法解析規則檔：" + ex.Message, "Batch Rename Studio Pro",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
            return;
        }

        _updatingUi = true;
        _applyToCombo.SelectedIndex = _rules.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
        _sortCombo.SelectedIndex = _rules.Sort switch
        {
            SortMode.Created => 1,
            SortMode.Modified => 2,
            _ => 0,
        };
        _updatingUi = false;

        SyncRuleList(_rules.Steps.Count > 0 ? 0 : -1);
        UpdateStatus("已載入規則：" + dialog.FileName);
        RefreshPreview();
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "儲存規則",
            FileName = "rules.json",
            Filter = "JSON (*.json)|*.json|所有檔案 (*.*)|*.*",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            JsonText.WriteFile(dialog.FileName, _rules.ToJson());
            UpdateStatus("已儲存規則：" + dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, "儲存失敗：" + ex.Message, "Batch Rename Studio Pro",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ShowRulesJson()
    {
        var text = new StringBuilder();
        text.Append(_rules.ToJson());
        text.Append('\n');
        text.Append("--- 對應的無介面指令 ---\n");
        text.Append("BatchRenameStudio.exe --plan --dir \"");
        text.Append(_folderBox.Text.Trim());
        text.Append("\" --rules rules.json --out plan.json\n");

        using var dialog = new Form
        {
            Text = "規則 JSON",
            StartPosition = FormStartPosition.CenterParent,
            ClientSize = new Size(640, 460),
            MinimizeBox = false,
            MaximizeBox = false,
            ShowInTaskbar = false,
        };

        var box = new TextBox
        {
            Dock = DockStyle.Fill,
            Multiline = true,
            ReadOnly = true,
            ScrollBars = ScrollBars.Both,
            WordWrap = false,
            Font = new Font(FontFamily.GenericMonospace, 9.5f),
            Text = text.ToString().Replace("\n", Environment.NewLine),
        };

        dialog.Controls.Add(box);
        dialog.ShowDialog(this);
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            _debounce.Dispose();
            _addMenu.Dispose();
        }

        base.Dispose(disposing);
    }
}

