using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Console plumbing for a single binary that is both a command-line tool and a windowed app.
/// <para>
/// The executable targets the console subsystem so that a shell waits for it and can read the
/// summary line and the exit code. When it is started without arguments the GUI path immediately
/// hides and releases that console, so launching from Explorer looks like an ordinary window.
/// </para>
/// </summary>
internal static class ConsoleBridge
{
    private const int AttachParentProcess = -1;
    private const int SwHide = 0;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FreeConsole();

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetConsoleWindow();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern int GetConsoleProcessList(uint[] processList, int processCount);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    private static bool _attached;

    /// <summary>Makes sure the headless path has somewhere to write its summary line.</summary>
    public static void Attach()
    {
        if (_attached) return;
        _attached = true;

        try
        {
            // Console subsystem: a console already exists (inherited or freshly allocated) and the
            // default Console writers are correct. The attach below only matters if this ever ships
            // as a WinExe again.
            if (GetConsoleWindow() != IntPtr.Zero) return;

            if (!AttachConsole(AttachParentProcess)) return;

            Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true });
            Console.SetError(new StreamWriter(Console.OpenStandardError()) { AutoFlush = true });
        }
        catch
        {
            // No console and no redirection: writes fall through to Stream.Null, which is fine.
        }
    }

    /// <summary>
    /// Releases the console before showing the window. The window is only hidden when this process
    /// is the sole owner of it — otherwise it would hide the terminal the user launched us from.
    /// </summary>
    public static void ReleaseForGui()
    {
        try
        {
            var console = GetConsoleWindow();
            if (console != IntPtr.Zero && IsSoleConsoleOwner()) ShowWindow(console, SwHide);
            FreeConsole();
        }
        catch
        {
            // Nothing to release; carry on and show the window.
        }
    }

    private static bool IsSoleConsoleOwner()
    {
        var buffer = new uint[8];
        var count = GetConsoleProcessList(buffer, buffer.Length);
        return count == 1;
    }
}

