using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is a WinExe so that double-clicking it never flashes a console window. That also
/// means it starts detached from the parent console, so headless mode re-attaches to it before
/// writing the summary line. When stdout is redirected to a file or a pipe this is a no-op —
/// the inherited handle already works.
/// </summary>
internal static class ConsoleBridge
{
    private const int AttachParentProcess = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    private static bool _attached;

    public static void Attach()
    {
        if (_attached) return;
        _attached = true;

        try
        {
            AttachConsole(AttachParentProcess);

            var stdout = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };
            Console.SetOut(stdout);

            var stderr = new StreamWriter(Console.OpenStandardError()) { AutoFlush = true };
            Console.SetError(stderr);
        }
        catch
        {
            // No console and no redirection: writes fall through to Stream.Null, which is fine.
        }
    }
}

