using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    /// <summary>
    /// With arguments the process behaves as a console tool (contracts A and B); with none it opens
    /// the rule editor. Both paths share <see cref="Core.RenameEngine"/>.
    /// </summary>
    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Length > 0) return HeadlessRunner.Run(args);

        ConsoleBridge.ReleaseForGui();

        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);

        try
        {
            Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
        }
        catch
        {
            // Older shells may refuse the mode change; the default DPI behaviour still works.
        }

        // A GUI failure must announce itself rather than vanish: once the console is released a
        // crash would otherwise leave nothing on screen at all.
        Application.ThreadException += (_, e) => ReportFatal(e.Exception);
        AppDomain.CurrentDomain.UnhandledException += (_, e) => ReportFatal(e.ExceptionObject as Exception);
        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);

        try
        {
            Application.Run(new MainForm());
        }
        catch (Exception ex)
        {
            ReportFatal(ex);
            return 1;
        }

        return 0;
    }

    private static void ReportFatal(Exception? exception)
    {
        var detail = exception?.ToString() ?? "Unknown error.";

        try
        {
            var logPath = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "BatchRenameStudio",
                "crash.log");
            Directory.CreateDirectory(Path.GetDirectoryName(logPath)!);
            File.AppendAllText(logPath, $"{DateTime.Now:o}{Environment.NewLine}{detail}{Environment.NewLine}{Environment.NewLine}");
            detail += Environment.NewLine + Environment.NewLine + "紀錄檔：" + logPath;
        }
        catch
        {
            // Logging is best effort; the dialog below is what the user actually needs.
        }

        MessageBox.Show(
            detail,
            "Batch Rename Studio Pro 發生未預期的錯誤",
            MessageBoxButtons.OK,
            MessageBoxIcon.Error);
    }
}

