/// <summary>Widens a drop-down so its longest entry is fully readable at any DPI.</summary>
private static void SizeComboToContent(ComboBox combo)
{
    var width = 0;
    foreach (var item in combo.Items)
        width = Math.Max(width, TextRenderer.MeasureText(item?.ToString() ?? string.Empty, combo.Font).Width);

    combo.Width = width + SystemInformation.VerticalScrollBarWidth + 16;
}

