using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Property editor for the selected rule. The form is generated from
/// <see cref="OpCatalog"/> so a new operation only has to be described once.
/// </summary>
public sealed class RuleEditorPanel : Panel
{
    private RuleStep? _step;
    private bool _suspendEvents;

    public RuleEditorPanel()
    {
        AutoScroll = true;
        Padding = new Padding(10);
        BackColor = AppTheme.PanelBackground;
    }

    /// <summary>Raised when the user edits a value; the host recomputes the preview.</summary>
    public event EventHandler? StepEdited;

    public void Bind(RuleStep? step)
    {
        _step = step;
        Rebuild();
    }

    private void Rebuild()
    {
        SuspendLayout();
        // Copy first: Dispose() detaches the control from Controls and would invalidate the enumerator.
        var previous = new Control[Controls.Count];
        Controls.CopyTo(previous, 0);
        Controls.Clear();
        foreach (var control in previous) control.Dispose();

        if (_step is null)
        {
            Controls.Add(new Label
            {
                Text = "在上方清單選擇一條規則即可編輯它的參數。",
                AutoSize = true,
                ForeColor = AppTheme.MutedText,
                Location = new Point(12, 12),
            });

            ResumeLayout(true);
            return;
        }

        var info = OpCatalog.Find(_step.Op);

        var table = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 2,
            Padding = new Padding(0, 0, 12, 0),
        };
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));

        var title = new Label
        {
            Text = info?.Title ?? $"{_step.Op} — 未知操作",
            AutoSize = true,
            Font = new Font(Font, FontStyle.Bold),
            Margin = new Padding(0, 0, 0, 2),
        };
        table.Controls.Add(title, 0, 0);
        table.SetColumnSpan(title, 2);

        var summary = new Label
        {
            Text = info?.Summary ?? "此操作不在 14 個已定義操作之內，執行時會被視為不做任何事。",
            AutoSize = true,
            MaximumSize = new Size(360, 0),
            ForeColor = AppTheme.MutedText,
            Margin = new Padding(0, 0, 0, 10),
        };
        table.Controls.Add(summary, 0, 1);
        table.SetColumnSpan(summary, 2);

        var row = 2;
        _suspendEvents = true;

        foreach (var field in OpCatalog.FieldsFor(_step.Op))
        {
            var label = new Label
            {
                Text = field.Label,
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(0, 7, 10, 4),
            };
            table.Controls.Add(label, 0, row);
            table.Controls.Add(BuildEditor(field), 1, row);
            row++;

            if (field.Hint.Length > 0)
            {
                var hint = new Label
                {
                    Text = field.Hint,
                    AutoSize = true,
                    MaximumSize = new Size(340, 0),
                    ForeColor = AppTheme.MutedText,
                    Margin = new Padding(0, 0, 0, 8),
                };
                table.Controls.Add(hint, 1, row);
                row++;
            }
        }

        if (OpCatalog.FieldsFor(_step.Op).Count == 0)
        {
            var none = new Label
            {
                Text = "這個操作沒有可調參數。",
                AutoSize = true,
                ForeColor = AppTheme.MutedText,
            };
            table.Controls.Add(none, 0, row);
            table.SetColumnSpan(none, 2);
        }

        _suspendEvents = false;
        Controls.Add(table);
        ResumeLayout(true);
    }

    private Control BuildEditor(OpField field)
    {
        var step = _step!;

        switch (field.Kind)
        {
            case OpFieldKind.Bool:
            {
                var box = new CheckBox
                {
                    AutoSize = true,
                    Checked = step.GetBool(field.Key, field.Default as bool? ?? false),
                    Margin = new Padding(0, 6, 0, 4),
                };
                box.CheckedChanged += (_, _) => Commit(field.Key, box.Checked);
                return box;
            }

            case OpFieldKind.Int:
            {
                var numeric = new NumericUpDown
                {
                    Width = 120,
                    Minimum = string.Equals(field.Key, "step", StringComparison.Ordinal) ? -999999 : 0,
                    Maximum = 999999,
                    Margin = new Padding(0, 4, 0, 4),
                };

                var current = step.GetInt(field.Key, Convert.ToInt32(field.Default ?? 0L));
                numeric.Value = Math.Clamp(current, (int)numeric.Minimum, (int)numeric.Maximum);
                numeric.ValueChanged += (_, _) => Commit(field.Key, (long)numeric.Value);
                return numeric;
            }

            case OpFieldKind.Choice:
            {
                var combo = new ComboBox
                {
                    DropDownStyle = ComboBoxStyle.DropDownList,
                    Width = 180,
                    Margin = new Padding(0, 4, 0, 4),
                };
                combo.Items.AddRange(field.Choices);

                var current = step.GetString(field.Key, field.Default as string ?? string.Empty);
                var selected = Array.FindIndex(field.Choices, c => string.Equals(c, current, StringComparison.OrdinalIgnoreCase));
                combo.SelectedIndex = selected >= 0 ? selected : 0;
                combo.SelectedIndexChanged += (_, _) => Commit(field.Key, combo.SelectedItem as string ?? string.Empty);
                return combo;
            }

            default:
            {
                var text = new TextBox
                {
                    Width = 260,
                    Margin = new Padding(0, 4, 0, 4),
                    Text = step.GetString(field.Key, field.Default as string ?? string.Empty),
                };
                text.TextChanged += (_, _) => Commit(field.Key, text.Text);
                return text;
            }
        }
    }

    private void Commit(string key, object? value)
    {
        if (_suspendEvents || _step is null) return;
        _step[key] = value;
        StepEdited?.Invoke(this, EventArgs.Empty);
    }
}

