public static bool TryGetGuiOptions(string[] args, out string? directory, out string? rulesPath)
{
    directory = null;
    rulesPath = null;
    var requested = false;

    for (var i = 0; i < args.Length; i++)
    {
        var (name, inlineValue) = SplitArgument(args[i]);
        switch (name)
        {
            case "--gui":
                requested = true;
                break;
            case "--dir":
                directory = inlineValue ?? (i + 1 < args.Length ? args[++i] : null);
                break;
            case "--rules":
                rulesPath = inlineValue ?? (i + 1 < args.Length ? args[++i] : null);
                break;
        }
    }

    return requested;
}

