/// <summary>
/// <paramref name="startDirectory"/> and <paramref name="startRulesPath"/> come from
/// <c>--gui --dir … --rules …</c> and simply pre-fill the window.
/// </summary>
public MainForm(string? startDirectory, string? startRulesPath)
{
    BuildUi();
    WireEvents();

    if (!string.IsNullOrWhiteSpace(startRulesPath) && File.Exists(startRulesPath))
    {
        try
        {
            _rules = RuleSet.Load(startRulesPath);
        }
        catch (Exception ex)
        {
            UpdateStatus("無法解析啟動規則檔：" + ex.Message);
        }
    }

    _updatingUi = true;
    _applyToCombo.SelectedIndex = _rules.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
    _sortCombo.SelectedIndex = _rules.Sort switch
    {
        SortMode.Created => 1,
        SortMode.Modified => 2,
        _ => 0,
    };
    _updatingUi = false;

    SyncRuleList(_rules.Steps.Count > 0 ? 0 : -1);

    if (!string.IsNullOrWhiteSpace(startDirectory)) _folderBox.Text = startDirectory;
    else UpdateStatus("請先選擇要處理的資料夾。");

    UpdateButtons();
}

