5	/// <summary>
6	/// Property editor for the selected rule. The form is generated from
7	/// <see cref="OpCatalog"/> so a new operation only has to be described once.
8	/// </summary>
9	public sealed class RuleEditorPanel : Panel
10	{
11	    private RuleStep? _step;
12	    private bool _suspendEvents;
13	
14	    public RuleEditorPanel()
15	    {
16	        AutoScroll = true;
17	        Padding = new Padding(10);
18	        BackColor = AppTheme.PanelBackground;
19	    }
20	
21	    /// <summary>Raised when the user edits a value; the host recomputes the preview.</summary>
22	    public event EventHandler? StepEdited;
23	
24	    public void Bind(RuleStep? step)
25	    {
26	        _step = step;
27	        Rebuild();
28	    }
29	
30	    private void Rebuild()
31	    {
32	        SuspendLayout();
33	        // Copy first: Dispose() detaches the control from Controls and would invalidate the enumerator.
34	        var previous = new Control[Controls.Count];
35	        Controls.CopyTo(previous, 0);
36	        Controls.Clear();
37	        foreach (var control in previous) control.Dispose();
38	
39	        if (_step is null)
40	        {
41	            Controls.Add(new Label
42	            {
43	                Text = "在上方清單選擇一條規則即可編輯它的參數。",
44	                AutoSize = true,
45	                ForeColor = AppTheme.MutedText,
46	                Location = new Point(12, 12),
47	            });
48	
49	            ResumeLayout(true);
50	            return;
51	        }
52	
53	        var info = OpCatalog.Find(_step.Op);
54	
55	        var table = new TableLayoutPanel
56	        {
57	            Dock = DockStyle.Top,
58	            AutoSize = true,
59	            AutoSizeMode = AutoSizeMode.GrowAndShrink,
60	            ColumnCount = 2,
61	            Padding = new Padding(0, 0, 12, 0),
62	        };
63	        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
64	        table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
65	
66	        var title = new Label
67	        {
68	            Text = info?.Title ?? $"{_step.Op} — 未知操作",
69	            AutoSize = true,
70	            Font = new Font(Font, FontStyle.Bold),
71	            Margin = new Padding(0, 0, 0, 2),
72	        };
73	        table.Controls.Add(title, 0, 0);
74	        table.SetColumnSpan(title, 2);
75	
76	        var summary = new Label
77	        {
78	            Text = info?.Summary ?? "此操作不在 14 個已定義操作之內，執行時會被視為不做任何事。",
79	            AutoSize = true,
80	            MaximumSize = new Size(460, 0),
81	            ForeColor = AppTheme.MutedText,
82	            Margin = new Padding(0, 0, 0, 10),
83	        };
84	        table.Controls.Add(summary, 0, 1);
85	        table.SetColumnSpan(summary, 2);
86	
87	        var row = 2;
88	        _suspendEvents = true;
89	
90	        foreach (var field in OpCatalog.FieldsFor(_step.Op))
91	        {
92	            var label = new Label
93	            {
94	                Text = field.Label,
95	                AutoSize = true,
96	                Anchor = AnchorStyles.Left,
97	                Margin = new Padding(0, 7, 10, 4),
98	            };
99	            table.Controls.Add(label, 0, row);
100	            table.Controls.Add(BuildEditor(field), 1, row);
101	            row++;
102	
103	            if (field.Hint.Length > 0)
104	            {
105	                var hint = new Label
106	                {
107	                    Text = field.Hint,
108	                    AutoSize = true,
109	                    MaximumSize = new Size(440, 0),
110	                    ForeColor = AppTheme.MutedText,
111	                    Margin = new Padding(0, 0, 0, 8),
112	                };
113	                table.Controls.Add(hint, 1, row);
114	                row++;
115	            }
116	        }
117	
118	        if (OpCatalog.FieldsFor(_step.Op).Count == 0)
119	        {
120	            var none = new Label
121	            {
122	                Text = "這個操作沒有可調參數。",
123	                AutoSize = true,
124	                ForeColor = AppTheme.MutedText,
125	            };
126	            table.Controls.Add(none, 0, row);
