147	                    Margin = new Padding(0, 6, 0, 4),
148	                };
149	                box.CheckedChanged += (_, _) => Commit(field.Key, box.Checked);
150	                return box;
151	            }
152	
153	            case OpFieldKind.Int:
154	            {
155	                var numeric = new NumericUpDown
156	                {
157	                    Width = 120,
158	                    Minimum = string.Equals(field.Key, "step", StringComparison.Ordinal) ? -999999 : 0,
159	                    Maximum = 999999,
160	                    Margin = new Padding(0, 4, 0, 4),
161	                };
162	
163	                var current = step.GetInt(field.Key, Convert.ToInt32(field.Default ?? 0L));
164	                numeric.Value = Math.Clamp(current, (int)numeric.Minimum, (int)numeric.Maximum);
165	                numeric.ValueChanged += (_, _) => Commit(field.Key, (long)numeric.Value);
166	                return numeric;
167	            }
168	
169	            case OpFieldKind.Choice:
170	            {
171	                var combo = new ComboBox
172	                {
173	                    DropDownStyle = ComboBoxStyle.DropDownList,
174	                    Width = 180,
175	                    Margin = new Padding(0, 4, 0, 4),
176	                };
177	                combo.Items.AddRange(field.Choices);
178	
179	                var current = step.GetString(field.Key, field.Default as string ?? string.Empty);
180	                var selected = Array.FindIndex(field.Choices, c => string.Equals(c, current, StringComparison.OrdinalIgnoreCase));
181	                combo.SelectedIndex = selected >= 0 ? selected : 0;
182	                combo.SelectedIndexChanged += (_, _) => Commit(field.Key, combo.SelectedItem as string ?? string.Empty);
183	                return combo;
184	            }
185	
186	            default:
187	            {
188	                var text = new TextBox
189	                {
190	                    // Stretches with the 100%-width column instead of clipping at a fixed size.
191	                    Anchor = AnchorStyles.Left | AnchorStyles.Right,
192	                    MinimumSize = new Size(180, 0),
193	                    Margin = new Padding(0, 4, 0, 4),
194	                    Text = step.GetString(field.Key, field.Default as string ?? string.Empty),
195	                };
196	                text.TextChanged += (_, _) => Commit(field.Key, text.Text);
197	                return text;
198	            }
199	        }
200	    }
201	
202	    private void Commit(string key, object? value)
203	    {
204	        if (_suspendEvents || _step is null) return;
205	        _step[key] = value;
206	        StepEdited?.Invoke(this, EventArgs.Empty);
207	    }
208	}
