cd D:\BenchRuns\XL-A-03
$exe = ".\src\BatchRenameStudio\bin\Release\net8.0-windows\BatchRenameStudio.exe"
$fx = "C:\Users\USER\AppData\Local\Temp\claude\D--BenchRuns-XL-A-03\8ad71272-8fa1-4cc4-9472-bcdc88bed834\scratchpad\fixture"
$out = "C:\Users\USER\AppData\Local\Temp\claude\D--BenchRuns-XL-A-03\8ad71272-8fa1-4cc4-9472-bcdc88bed834\scratchpad"
$all = $true
foreach ($r in (Get-ChildItem samples\rules\*.json)) {
  & $exe --plan    --dir $fx --rules $r.FullName --out "$out\p.json" | Out-Null
  & $exe --explain --dir $fx --rules $r.FullName --out "$out\t.json" | Out-Null
  $p = Get-Content "$out\p.json" -Raw | ConvertFrom-Json
  $t = Get-Content "$out\t.json" -Raw | ConvertFrom-Json
  $rs = Get-Content $r.FullName -Raw | ConvertFrom-Json
  $n = $rs.steps.Count
  $ok = $true
  for ($i=0; $i -lt $p.items.Count; $i++) {
    if ($p.items[$i].original -ne $t.files[$i].original) { $ok = $false }
    if ($p.items[$i].proposed -ne $t.files[$i].proposed) { $ok = $false }
    if ($p.items[$i].status   -ne $t.files[$i].status)   { $ok = $false }
    if ($t.files[$i].steps.Count -ne $n) { $ok = $false }
    for ($s=0; $s -lt $n; $s++) { if ($t.files[$i].steps[$s].index -ne $s) { $ok = $false } }
  }
  "{0,-28} files={1} steps={2} plan/trace-agree={3}" -f $r.Name, $p.items.Count, $n, $ok
  if (-not $ok) { $all = $false }
}
"ALL CONSISTENT = $all"
